async function metricStorageGet(defaults = {}, options = {}) {
    incrementQueueWakeupMetric('storageGetCalls')
    incrementActiveStorageMetricDetail('storageGetCalls')
    const pathName = getStorageMetricPathName(options)
    const updateToken = getActiveStorageUpdateToken()
    const storageContext = getActiveStorageContext()
    const startedAt = Date.now()
    let result = null
    try {
        result = await runQueueWakeupMetricPhase(options.phase || 'storageGet', () => coordinatorStorageAdapter.get(defaults))
    }
    finally {
        recordStoragePathLatencyMetrics('read', pathName, Date.now() - startedAt)
    }
    if(updateToken && isStorageUpdateAbandoned(updateToken)) {
        if(storageContext) {
            storageContext.lateWriteSuppressed = true
            storageContext.abortedOperation = 'storageGet'
        }
        incrementQueueWakeupMetric('storageUpdate.lateWriteSuppressed')
        setActiveStorageMetricDetail('lateWriteSuppressed', true)
        setActiveStorageMetricDetail('abortedOperation', 'storageGet')
        throw new Error('abandoned storage update suppressed after storageGet')
    }
    recordStorageReadPayloadMetrics(result, pathName)
    return result
}

// The space post maps on disk (spaceMapStorage.js). spaceMapLayout.bucketed is true once the disk holds the bucketed layout.
// hashes are the bucket hashes last written or loaded for each map, so a write sends only the buckets that changed. Before the
// layout is bucketed, the legacy whole-map keys are written as before, so nothing changes until the migration has run.
const spaceMapLayout = {
    bucketed: false,
    hashes: {[SPACE_NUKED_POSTS_KEY]: null, [SPACE_PENDING_NUKED_POSTS_KEY]: null}
}
const SPACE_MAP_KEYS = [SPACE_NUKED_POSTS_KEY, SPACE_PENDING_NUKED_POSTS_KEY]

function getSpaceMapStoredReadDefaults() {
    return Object.fromEntries(spaceMapStorageKeys(SPACE_MAP_KEYS).map(key => [key, key === SPACE_MAP_LAYOUT_KEY ? null : {}]))
}

// Reads the layout from a hydrate read: the maps become whole maps in stored (as before), and the layout and bucket keys are removed.
function applySpaceMapStoredLayout(stored = {}) {
    const bucketed = stored[SPACE_MAP_LAYOUT_KEY] === SPACE_MAP_LAYOUT_BUCKETED
    const maps = {}
    for(const key of SPACE_MAP_KEYS) maps[key] = readSpaceMapFromStored(stored, key)
    for(const key of spaceMapStorageKeys(SPACE_MAP_KEYS)) delete stored[key]
    Object.assign(stored, maps)
    spaceMapLayout.bucketed = bucketed
    spaceMapLayout.hashes = {}
    for(const key of SPACE_MAP_KEYS) {
        spaceMapLayout.hashes[key] = bucketed ? hashSpaceMapBuckets(splitSpaceMapIntoBuckets(key, maps[key])) : null
    }
}

// The write a payload turns into on disk. A migration writes both maps as buckets, with the layout marker, and ignores the
// last hashes. An ordinary write of a bucketed layout writes only the changed buckets. Anything else is written as it came.
function getSpaceMapDiskWrite(payload = {}, options = {}) {
    const migrating = options.spaceMapMigrate === true
    const mapKeys = SPACE_MAP_KEYS.filter(key => Object.prototype.hasOwnProperty.call(payload, key))
    if(!mapKeys.length) return {disk: payload, hashes: null, migrated: false}
    if(migrating && mapKeys.length !== SPACE_MAP_KEYS.length) return {disk: payload, hashes: null, migrated: false}
    if(!migrating && !spaceMapLayout.bucketed) return {disk: payload, hashes: null, migrated: false}
    const disk = {...payload}
    const hashes = {}
    for(const key of mapKeys) delete disk[key]
    for(const key of mapKeys) {
        const previous = migrating ? null : spaceMapLayout.hashes[key]
        const next = changedSpaceMapBuckets(key, payload[key], previous)
        Object.assign(disk, next.changed)
        hashes[key] = next.hashes
    }
    if(migrating) disk[SPACE_MAP_LAYOUT_KEY] = SPACE_MAP_LAYOUT_BUCKETED
    return {disk, hashes, migrated: migrating}
}

// The bytes a translated write puts on disk (the JSON of each value), for the flight recorder. The logical payload is larger.
function measureDiskWriteBytes(disk = {}) {
    let total = 0
    for(const value of Object.values(disk)) total += JSON.stringify(value ?? null).length
    return total
}

// Called only after the disk write succeeded. A failed write leaves the hashes as they were, so the next write sends the same buckets again.
function commitSpaceMapDiskWrite(write = {}) {
    if(!write.hashes) return
    for(const key of Object.keys(write.hashes)) spaceMapLayout.hashes[key] = write.hashes[key]
    if(write.migrated) spaceMapLayout.bucketed = true
}

// The run list (COORDINATOR_RUNS_KEY) on disk. Same scheme as the space maps, with its own layout marker, so the two can be
// migrated separately. The session mirror of the run list stays whole. Its disk copy is the buckets once runsLayout.bucketed.
const COORDINATOR_RUNS_LAYOUT_KEY = 'mbCoordinatorRunsLayoutVersion'
const runsLayout = {bucketed: false, hash: null}

function getRunsStoredReadDefaults() {
    return {[COORDINATOR_RUNS_LAYOUT_KEY]: null, [COORDINATOR_RUNS_KEY]: {}, ...Object.fromEntries(spaceMapBucketKeys(COORDINATOR_RUNS_KEY).map(key => [key, {}]))}
}

// The layout keys only: used when the run list comes from the session mirror, so the legacy key is not read from disk.
function getRunsLayoutStoredReadDefaults() {
    return {[COORDINATOR_RUNS_LAYOUT_KEY]: null, ...Object.fromEntries(spaceMapBucketKeys(COORDINATOR_RUNS_KEY).map(key => [key, {}]))}
}

// From a hydrate read. fromMirror: the run list is the session copy, already in stored, and only the layout is read from disk.
function applyRunsStoredLayout(stored = {}, options = {}) {
    const bucketed = stored[COORDINATOR_RUNS_LAYOUT_KEY] === SPACE_MAP_LAYOUT_BUCKETED
    const runs = options.fromMirror === true ? (stored[COORDINATOR_RUNS_KEY] || {}) : readSpaceMapFromStored(stored, COORDINATOR_RUNS_KEY)
    for (const key of [COORDINATOR_RUNS_LAYOUT_KEY, ...spaceMapBucketKeys(COORDINATOR_RUNS_KEY)]) delete stored[key]
    stored[COORDINATOR_RUNS_KEY] = runs
    runsLayout.bucketed = bucketed
    runsLayout.hash = bucketed ? hashSpaceMapBuckets(splitSpaceMapIntoBuckets(COORDINATOR_RUNS_KEY, runs)) : null
}

// The disk write of the run list. Once bucketed, a write sends only the changed buckets; a migration writes all of them with the marker.
function getRunsDiskWrite(payload = {}, options = {}) {
    if (!Object.prototype.hasOwnProperty.call(payload, COORDINATOR_RUNS_KEY)) return {disk: payload, hashes: null, migrated: false}
    const migrating = options.runsMigrate === true
    if (!migrating && !runsLayout.bucketed) return {disk: payload, hashes: null, migrated: false}
    const disk = {...payload}
    delete disk[COORDINATOR_RUNS_KEY]
    const next = changedSpaceMapBuckets(COORDINATOR_RUNS_KEY, payload[COORDINATOR_RUNS_KEY], migrating ? null : runsLayout.hash)
    Object.assign(disk, next.changed)
    if (migrating) disk[COORDINATOR_RUNS_LAYOUT_KEY] = SPACE_MAP_LAYOUT_BUCKETED
    return {disk, hashes: next.hashes, migrated: migrating}
}

function commitRunsDiskWrite(write = {}) {
    if (!write.hashes) return
    runsLayout.hash = write.hashes
    if (write.migrated) runsLayout.bucketed = true
}

async function metricStorageSet(payload = {}, options = {}) {
    const storageContext = getActiveStorageContext()
    if(payload &&
        typeof payload === 'object' &&
        Object.prototype.hasOwnProperty.call(payload, COORDINATOR_QUEUE_KEY) &&
        storageContext?.coordinatorAuthorityQueueMutationApplied === true &&
        options.coordinatorAuthorityWrite !== true) {
        incrementQueueWakeupMetric('coordinatorAuthority.postMutationQueueStorageSetRejected')
        setActiveStorageMetricDetail('rejectedOperation', 'postAuthorityQueueStorageSet')
        return false
    }
    payload = addContentPageStateProjectionPayload(payload)
    const keys = Object.keys(payload || {})
    if(!keys.length) return
    if(Object.prototype.hasOwnProperty.call(payload, COORDINATOR_PAUSED_KEY)) {
        recordCoordinatorPauseTransition(payload[COORDINATOR_PAUSED_KEY] === true)
        storedCoordinatorPausedMirror = payload[COORDINATOR_PAUSED_KEY] === true
    }
    if(suppressAbandonedStorageOperation('storageSet')) return false
    if(options.snapshotWriteReason) {
        recordSnapshotWriteReasonMetrics(options.snapshotWriteReason, payload)
    }
    const pathName = getStorageMetricPathName(options)
    // Review F2 / decision 30: the resume exemption is decided by the keys this write carries, not by its label (swResumeExemption.js).
    const resumeWrite = classifyStorageWriteForResume(keys, {viewKey: PROFILE_NUKE_PROGRESS_VIEW_KEY, shardPrefix: PROFILE_NUKE_PROGRESS_SHARD_PREFIX})
    const isProfileProgressProjectionWrite = resumeWrite.wroteProgress
    // Owner 18 Oct: every write is labelled. A write with no label falls back to its phase, so it is counted here to make it visible.
    if(!options.metricPath && !options.callPath && !options.reason && !options.snapshotWriteReason) {
        incrementQueueWakeupMetric('storagePayload.write.unlabelled')
    }
    const payloadSummary = recordStoragePayloadMetrics(payload, pathName)
    recordQueueWriteOperationMetrics(payload, options)
    incrementQueueWakeupMetric('storageSetCalls')
    incrementActiveStorageMetricDetail('storageSetCalls')
    applyResumeExemptionToUpdate(storageContext, resumeWrite)
    const startedAt = Date.now()
    let result = null
    let writeOutcome = 'error'
    // Bytes actually written to disk, set only when the write was turned into space map buckets (the logical payload is larger).
    let diskWriteBytes = null
    try {
        if(isProfileProgressProjectionWrite) profileNukeProgressProjectionWriteDepth += 1
        // A namespace write's stamps (writeCoordinatorStoredKeys) join the keys in this one adapter call. They are added here,
        // not to payload, so the metrics, the idle latch and the dashboard notify see exactly what the caller wrote.
        const spaceMapWrite = getSpaceMapDiskWrite(payload, options)
        const runsWrite = getRunsDiskWrite(spaceMapWrite.disk, options)
        const diskPayload = options.namespaceStamps ? {...runsWrite.disk, ...options.namespaceStamps} : runsWrite.disk
        if(spaceMapWrite.hashes || runsWrite.hashes) diskWriteBytes = measureDiskWriteBytes(diskPayload)
        result = await runQueueWakeupMetricPhase(options.phase || 'storageSet', () => (Object.keys(diskPayload).length
            ? coordinatorStorageAdapter.set(diskPayload)
            : true))
        if(result !== false) {
            commitSpaceMapDiskWrite(spaceMapWrite)
            commitRunsDiskWrite(runsWrite)
        }
        writeOutcome = 'saved'
    }
    finally {
        if(isProfileProgressProjectionWrite) {
            profileNukeProgressProjectionWriteDepth = Math.max(0, profileNukeProgressProjectionWriteDepth - 1)
        }
        const writeElapsedMs = Date.now() - startedAt
        recordStoragePathLatencyMetrics('write', pathName, writeElapsedMs)
        // Per-key latency, alongside the existing per-path breakdown -- the
        // compact queue view alone gets written from several different
        // call sites, each with its own metricPath, so there was no single
        // place to read "how long do queue-view writes take" without
        // summing across paths by hand.
        for(const key of keys) {
            recordStorageKeyLatencyMetrics('write', key, writeElapsedMs)
        }
        // One flight-recorder entry per write (owner 18 Oct): the label, the size in bytes, the rows, the keys, the time, and the
        // outcome. A write that throws is recorded as 'error' before the error reaches the caller.
        recordFlightRecorderEvent({
            kind: 'storage-write',
            source: 'metricStorageSet',
            label: pathName,
            bytes: diskWriteBytes ?? (payloadSummary?.bytes || 0),
            logicalBytes: payloadSummary?.bytes || 0,
            rows: payloadSummary?.rows || 0,
            keys: (payloadSummary?.keys || keys).slice(0, 12).join(','),
            elapsedMs: writeElapsedMs,
            outcome: writeOutcome,
            accepted: writeOutcome === 'saved',
            changed: writeOutcome === 'saved'
        })
    }
    if(isProfileProgressProjectionWrite) {
        profileNukeProgressProjectionVersion += 1
    }
    if(options.suppressDashboardNotify !== true) {
        notifyCoordinatorDashboardStateChanged(keys, pathName, payload)
    }
    return result
}

async function metricStorageRemove(keys = [], options = {}) {
    const normalizedKeys = Array.from(new Set((Array.isArray(keys) ? keys : [keys])
        .map(key => `${key || ''}`.trim())
        .filter(Boolean)))
    if(!normalizedKeys.length) return true
    if(suppressAbandonedStorageOperation('storageRemove')) return false

    const pathName = getStorageMetricPathName(options)
    incrementQueueWakeupMetric('storageRemoveCalls')
    incrementQueueWakeupMetric(`storageRemove.${normalizeStorageMetricPathName(pathName)}.keys`, normalizedKeys.length)
    recordQueueWakeupMetricMax(`storageRemove.${normalizeStorageMetricPathName(pathName)}.maxKeys`, normalizedKeys.length)
    incrementActiveStorageMetricDetail('storageRemoveCalls')
    setActiveStorageMetricDetail('removeKeys', normalizedKeys.slice(0, 12).join(','))
    setActiveStorageMetricDetail('removePath', normalizeStorageMetricPathName(pathName))

    const startedAt = Date.now()
    try {
        await runQueueWakeupMetricPhase(options.phase || 'storageRemove', () => coordinatorStorageAdapter.remove(normalizedKeys))
        return true
    }
    finally {
        recordStoragePathLatencyMetrics('write', pathName, Date.now() - startedAt)
    }
}

async function getLiveQueuedWorkerSurfaceProfileTabCount(targetProfileHref = '', preloadedTabs = null) {
    if(!browser.tabs?.query) return 0

    const normalizedTargetProfileHref = normalizeQuoraProfileUrl(targetProfileHref || '')
    // A fill pass passes the tab list it already read (owner 18 Oct). Otherwise the list is read here.
    const tabs = Array.isArray(preloadedTabs) ? preloadedTabs : await browser.tabs.query({}).catch(() => [])
    const tabsByWindow = new Map()
    const surfaceWindowIds = new Set()
    const addSurfaceWindowId = value => {
        const windowId = Number.parseInt(value, 10) || 0
        if(windowId) surfaceWindowIds.add(windowId)
    }

    addSurfaceWindowId(queuedActionSurfaceWindowId)
    for(const tab of tabs || []) {
        const windowId = Number.parseInt(tab?.windowId, 10) || 0
        if(!windowId) continue
        if(!tabsByWindow.has(windowId)) tabsByWindow.set(windowId, [])
        tabsByWindow.get(windowId).push(tab)
        if(isQueuedWorkerActionSurfaceUrl(tab?.url || '')) addSurfaceWindowId(windowId)
    }

    for(const tabId of queueRuntime.listActiveQueuedTabIds()) {
        const metadata = getQueuedTabMetadata(tabId)
        addSurfaceWindowId(metadata?.actionSurfaceWindowId)
        addSurfaceWindowId(metadata?.ownerWindowId)
    }
    for(const action of queueRuntime.listPendingTabActions()) {
        if(action?.actionSurfaceMode !== 'worker-window') continue
        addSurfaceWindowId(action?.actionSurfaceWindowId)
        addSurfaceWindowId(action?.ownerWindowId)
    }
    for(const action of queueRuntime.listActivationIntents()) {
        if(action?.actionSurfaceMode !== 'worker-window') continue
        addSurfaceWindowId(action?.actionSurfaceWindowId)
        addSurfaceWindowId(action?.ownerWindowId)
    }

    let count = 0
    for(const windowId of surfaceWindowIds) {
        const windowTabs = tabsByWindow.get(windowId) || []
        for(const tab of windowTabs) {
            const tabProfileHref = normalizeQuoraProfileUrl(tab?.url || '')
            if(!tabProfileHref) continue
            if(normalizedTargetProfileHref && tabProfileHref !== normalizedTargetProfileHref) continue
            count += 1
        }
    }
    return count
}

async function getLiveQueuedProfileTabCount() {
    if(!browser.tabs?.query) return 0

    const tabs = await browser.tabs.query({}).catch(() => [])
    return (tabs || []).filter(tab => normalizeQuoraProfileUrl(tab?.url || '')).length
}

