async function persistCoordinatorReconcileQueueAuthorityMutation(originalQueue = {}, nextState = {}, options = {}) {
    const operationKind = normalizeQueueWriteOperationName(options.operationKind || 'reconcile-progress')
    const diff = buildCoordinatorReconcileQueueAuthorityDiff(
        originalQueue,
        nextState?.queue || {},
        operationKind
    )
    if(!diff.results.length && !diff.removedRows.length) {
        return {
            saved: true,
            backend: 'queue-wal',
            reason: 'no-queue-diff',
            changedRows: 0
        }
    }

    // The prune removes past-retention rows, and since 2026-10-13 it archives them rather than discarding them (see
    // swCoordinatorProgressRules.js pruneCoordinatorCurrentWork). A pruned row that the diff removes is written to the
    // completed-work log in this same door write, with the shape archiveTerminalCoordinatorRow writes. Every other removal
    // in the diff is written as before.
    const prunedRowKeys = new Set(Array.isArray(options.prunedRowKeys) ? options.prunedRowKeys : [])
    const removedRows = diff.removedRows.map(removal => (prunedRowKeys.has(removal.rowKey)
        ? {...removal, operationKind: 'archive-terminal-row', reason: 'ordinaryMutation'}
        : removal))
    const completedRows = removedRows
        .filter(removal => prunedRowKeys.has(removal.rowKey))
        .map(removal => ({...removal}))

    // A pruned row that is finished is pushed into the baseline in this same write (persistCoordinatorWithFinishedOutliers).
    const persistence = await persistCoordinatorWithFinishedOutliers(
        {
            results: diff.results,
            removedRows,
            completedRows
        },
        {
            operationKind,
            reason: 'reconcile',
            metricPath: 'reconcile.queueWal.save',
            projectionMetricPath: 'reconcile.queueWal.projection'
        }
    )
    if(persistence?.saved === true) {
        return {
            ...persistence,
            changedRows: diff.results.length + diff.removedRows.length
        }
    }

    return {
        ...(persistence || {}),
        saved: false,
        changedRows: diff.results.length + diff.removedRows.length
    }
}

async function loadCoordinatorReconcileAuthorityPhase(options = {}) {
    const state = await coordinatorQueueReader.reconcile({
        metricPath: 'reconcile.load'
    })
    const queue = state.queue
    let runs = state.runs
    let pendingPosts = state.pendingPosts || {}
    let nukedPosts = state.nukedPosts || {}
    state.pendingPosts = pendingPosts
    state.nukedPosts = nukedPosts

    return {
        options,
        state,
        queue,
        originalQueue: cloneCoordinatorAuthorityValue(queue || {}),
        runs,
        originalRuns: cloneCoordinatorAuthorityValue(runs),
        events: state.events,
        progress: state.progress,
        originalProgress: cloneCoordinatorAuthorityValue(state.progress || {}),
        pendingPosts,
        nukedPosts,
        now: Date.now(),
        liveProfileTabsByHref: new Map(),
        changed: false,
        eventsChanged: false,
        pendingPostsChanged: false,
        nukedPostsChanged: false,
        progressChanged: false,
        runsMetadataChanged: false,
        materialized: 0,
        recomputeAllRuns: false,
        affectedRunIds: new Set(),
        terminalSettlementHrefs: new Set(),
        tabsToCloseAfterReconcile: new Set(),
        progressReconcileDeferredKeys: new Set()
    }
}

async function reconcileCoordinatorRuntimeActorsPhase(ctx = {}) {
    ctx.liveProfileTabsByHref = await getLiveProfileTabsByHref()
}

async function applyCoordinatorReconcileQueueAuthorityTransitionPhase(ctx = {}) {
    const {
        state,
        queue,
        progress,
        now
    } = ctx

    // Rows the prune removes are archived by the reconcile's own door write (persistCoordinatorReconcileQueueAuthorityMutation),
    // so their keys travel on ctx to that write.
    const prunedRowKeys = []
    if(pruneCoordinatorCurrentWork(queue, now, prunedRowKeys)) {
        ctx.changed = true
        ctx.recomputeAllRuns = true
    }
    ctx.prunedRowKeys = prunedRowKeys

    const progressReconcileQueueKeys = Object.keys(queue)
    const progressReconcileTailWindowKeys = new Set()
    if(progressReconcileQueueKeys.length) {
        const resumeIndex = progressReconcileTailResumeKey
            ? progressReconcileQueueKeys.indexOf(progressReconcileTailResumeKey)
            : 0
        const startIndex = resumeIndex >= 0 ? resumeIndex : 0
        const windowSize = Math.min(COORDINATOR_PROGRESS_RECONCILE_CHUNK_SIZE, progressReconcileQueueKeys.length)
        for(let offset = 0; offset < windowSize; offset += 1) {
            progressReconcileTailWindowKeys.add(progressReconcileQueueKeys[(startIndex + offset) % progressReconcileQueueKeys.length])
        }
        progressReconcileTailResumeKey = progressReconcileQueueKeys[(startIndex + windowSize) % progressReconcileQueueKeys.length]
    }
    else {
        progressReconcileTailResumeKey = null
    }

    for(const [itemKey, rawItem] of Object.entries(queue)) {
        let item = rawItem
        if(!item || typeof item !== 'object') continue

        if(item.runId) {
            const inferredSource = makeCoordinatorSourceFromRunMetadata(item.runId || '', ctx.runs[item.runId] || {})
            const sourceMaterializedItem = applyCoordinatorSourceMetadataMaterialization(item, inferredSource)
            if(sourceMaterializedItem !== item) {
                item = sourceMaterializedItem
                queue[itemKey] = item
                ctx.changed = true
                ctx.materialized += 1
                markCoordinatorReconcileRunAffected(ctx, item)
            }
        }

        const terminalKeyOnlyDerivedMaterialization = materializeTerminalKeyOnlyDerivedStateLocked(state, itemKey, item, now)
        if(terminalKeyOnlyDerivedMaterialization.changed) {
            ctx.eventsChanged = ctx.eventsChanged || terminalKeyOnlyDerivedMaterialization.eventsChanged
            ctx.materialized += terminalKeyOnlyDerivedMaterialization.materialized || 0
        }
        addCoordinatorReconcileAffectedRunIds(ctx, terminalKeyOnlyDerivedMaterialization.affectedRunIds)

        const terminalResolverPendingSettlement = settleTerminalResolverPendingSourceRecordsLocked(state, itemKey, item)
        if(terminalResolverPendingSettlement.changed) {
            ctx.pendingPosts = terminalResolverPendingSettlement.pendingPosts || ctx.pendingPosts
            ctx.pendingPostsChanged = ctx.pendingPostsChanged || terminalResolverPendingSettlement.pendingPostsChanged
            ctx.materialized += terminalResolverPendingSettlement.materialized || 0
        }

        const resolvedResolverPendingSettlement = settleResolvedResolverPendingSourceRecordsLocked(state, itemKey, item)
        if(resolvedResolverPendingSettlement.changed) {
            ctx.pendingPosts = resolvedResolverPendingSettlement.pendingPosts || ctx.pendingPosts
            ctx.pendingPostsChanged = ctx.pendingPostsChanged || resolvedResolverPendingSettlement.pendingPostsChanged
            ctx.materialized += resolvedResolverPendingSettlement.materialized || 0
        }

        const queuedDerivedMaterialization = materializeQueuedCoordinatorDerivedStateLocked(state, itemKey, item, now)
        if(queuedDerivedMaterialization.changed) {
            ctx.runsMetadataChanged = ctx.runsMetadataChanged || queuedDerivedMaterialization.runsChanged
            ctx.progressChanged = ctx.progressChanged || queuedDerivedMaterialization.progressChanged
            ctx.eventsChanged = ctx.eventsChanged || queuedDerivedMaterialization.eventsChanged
            ctx.materialized += queuedDerivedMaterialization.materialized || 0
        }
        addCoordinatorReconcileAffectedRunIds(ctx, queuedDerivedMaterialization.affectedRunIds)

        const href = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey)
        let record = getCoordinatorProgressRecordForItem(itemKey, item, progress)
        if(record && !shouldApplyProgressToCoordinatorItem(item, record)) {
            record = null
        }
        if(record && hasMismatchedCoordinatorAttempt(item, record)) {
            await recordStaleAttemptDiagnostic({
                profileHref: href,
                incomingAttemptId: getAttemptIdFromValue(record),
                expectedAttemptId: getAttemptIdFromValue(item),
                senderTabId: record.tabId || null,
                message: 'Ignored reconcile from stale coordinator attempt'
            })
            record = null
        }

        // Everything from here down can await a real browser.tabs lookup
        // (shouldImmediatelyReconcileMissingPersistedActiveTab, getMissingActiveCoordinatorReconcileDecision,
        // getPersistedLiveTabForCoordinatorItem) for rows still claimed
        // active/settling, or for queue-authoritative rows whose progress
        // record now maps to terminal but which still carry a persisted
        // tabId -- exactly the rows a paused-then-resumed batch accumulates
        // by the hundreds once their persisted tabs are long gone. See
        // COORDINATOR_PROGRESS_RECONCILE_CHUNK_SIZE's comment: cap how many
        // rows run this tail per tick (via the rotating window built above,
        // so the same already-resolved rows can't monopolize every tick's
        // budget) and defer the rest to a follow-up reconcile rather than
        // holding the write-queue lock for the whole backlog in one pass.
        // Deferred rows still got their cheap, non-awaiting derived-state
        // materialization above this point on every pass, so nothing about
        // them goes stale -- only this tail's tab-status-driven transition
        // waits for a later tick.
        if(!progressReconcileTailWindowKeys.has(itemKey)) {
            ctx.progressReconcileDeferredKeys.add(itemKey)
            incrementQueueWakeupMetric('reconcile.progressReconcileChunked')
            continue
        }

        const invalidProfileResolutionFailure = getInvalidProfileResolutionFailure(item, itemKey)
        const invalidTerminalResolutionNeedsReconcile = isTerminalCoordinatorStatus(item.status) &&
            item.status === 'failed' &&
            item.outcome === 'action-error'
        if(invalidProfileResolutionFailure && (!isTerminalCoordinatorStatus(item.status) || invalidTerminalResolutionNeedsReconcile)) {
            const tabId = getPersistedQueuedTabId(item, record)
            const closePersistedTab = tabId
                ? !!await getPersistedLiveTabForCoordinatorItem(item, record, itemKey)
                : false
            const applied = applyInvalidProfileResolutionReconcileActionLocked({
                queue,
                pendingPosts: ctx.pendingPosts
            }, {
                kind: 'reconcileInvalidProfileResolution',
                itemKey,
                failure: invalidProfileResolutionFailure,
                expectedAttemptId: getAttemptIdFromValue(item),
                expectedAttemptNumber: getAttemptNumberFromValue(item),
                persistedTabId: tabId,
                closePersistedTab,
                requestedUrl: getProfileResolutionRequestedUrl(item, itemKey),
                record,
                now
            })
            if(applied.changed) {
                ctx.pendingPosts = applied.pendingPosts || ctx.pendingPosts
                ctx.pendingPostsChanged = ctx.pendingPostsChanged || applied.pendingPostsChanged
                ctx.changed = true
                ctx.materialized += applied.materialized || 0
                addCoordinatorReconcileAffectedRunIds(ctx, applied.affectedRunIds)
                for(const closeTabId of applied.tabIdsToClose || []) {
                    if(closeTabId) ctx.tabsToCloseAfterReconcile.add(closeTabId)
                }
            }
            continue
        }
        const persistedActiveTabMissing = await shouldImmediatelyReconcileMissingPersistedActiveTab(item, record)
        if(!href && (persistedActiveTabMissing || await shouldReconcileMissingActiveCoordinatorKeyOnlyItem(item, record, now))) {
            const tabId = getPersistedQueuedTabId(item, record)
            const closePersistedTab = tabId && !persistedActiveTabMissing
                ? !!await getPersistedLiveTabForCoordinatorItem(item, record, itemKey)
                : false
            const applied = applyStaleProfileResolutionTabReconcileActionLocked({
                queue
            }, {
                kind: 'reconcileStaleProfileResolutionTab',
                itemKey,
                expectedAttemptId: getAttemptIdFromValue(item),
                expectedAttemptNumber: getAttemptNumberFromValue(item),
                persistedTabId: tabId,
                closePersistedTab,
                record,
                now
            })
            if(applied.changed) {
                ctx.changed = true
                ctx.materialized += applied.materialized || 0
                addCoordinatorReconcileAffectedRunIds(ctx, applied.affectedRunIds)
                for(const closeTabId of applied.tabIdsToClose || []) {
                    if(closeTabId) ctx.tabsToCloseAfterReconcile.add(closeTabId)
                }
            }
            continue
        }
        const queueAuthoritative = isCoordinatorQueueAuthoritativeItem(item)
        let reconciledMissingActive = false
        const missingActiveDecision = await getMissingActiveCoordinatorReconcileDecision(
            item,
            record,
            itemKey,
            href,
            ctx.liveProfileTabsByHref,
            now,
            persistedActiveTabMissing
        )
        if(missingActiveDecision.reconcile) {
            const tabId = getPersistedQueuedTabId(item, record)
            const expectedLiveTabIds = getOwnedOrExpectedLiveTabsForProfileHref(item, record, href, ctx.liveProfileTabsByHref)
                .map(tab => normalizeTabId(tab?.id))
                .filter(liveTabId => liveTabId && liveTabId !== tabId)
            const applied = applyMissingActiveCoordinatorEvidenceReconcileActionLocked(state, {
                itemKey,
                href,
                persistedTabId: tabId,
                expectedAttemptId: getAttemptIdFromValue(item),
                expectedAttemptNumber: getAttemptNumberFromValue(item),
                closePersistedTab: missingActiveDecision.closePersistedTab === true,
                expectedLiveTabIds,
                now: Date.now()
            })
            if(applied.changed) {
                record = progress[applied.href] || record
                ctx.progressChanged = ctx.progressChanged || applied.progressChanged
                ctx.materialized += applied.materialized || 0
                reconciledMissingActive = true
                addCoordinatorReconcileAffectedRunIds(ctx, applied.affectedRunIds)
                for(const closeTabId of applied.tabIdsToClose || []) {
                    if(closeTabId) ctx.tabsToCloseAfterReconcile.add(closeTabId)
                }
            }
        }

        let mappedForAuthoritativeItem = null
        if(queueAuthoritative && !reconciledMissingActive) {
            mappedForAuthoritativeItem = getCoordinatorStatusFromProgress(record)
            const mappedTerminal = isTerminalCoordinatorStatus(mappedForAuthoritativeItem.status)
            const persistedTabId = mappedTerminal ? getPersistedQueuedTabId(item, record) : null
            const hasLiveAuthoritativeTab = persistedTabId
                ? !!await getPersistedLiveTabForCoordinatorItem(item, record, itemKey)
                : false

            if(!mappedTerminal || hasLiveAuthoritativeTab) {
                if(shouldRestoreTerminalProgressFromCoordinatorItem(item, record)) {
                    const restoredRecord = makeTerminalProgressRecordFromCoordinatorItem(
                        href,
                        item,
                        record,
                        'Restored terminal profile progress during authoritative queue reconcile'
                    )
                    if(restoredRecord && JSON.stringify(restoredRecord) !== JSON.stringify(record)) {
                        const recordHref = normalizeQuoraProfileUrl(href || restoredRecord.profileHref || '')
                        progress[recordHref] = restoredRecord
                        profileNukeProgress = {
                            ...profileNukeProgress,
                            [recordHref]: restoredRecord
                        }
                        ctx.progressChanged = true
                        ctx.materialized += 1
                        markCoordinatorReconcileRunAffected(ctx, item)
                    }
                }
                continue
            }
        }

        const mapped = mappedForAuthoritativeItem || getCoordinatorStatusFromProgress(record)
        if(!mapped.status) continue
        const resetRetry = shouldResetCoordinatorFailureFromProgress(item, record, mapped)
        const mappedTerminal = isTerminalCoordinatorStatus(mapped.status)
        if(isTerminalCoordinatorStatus(item.status) && !mappedTerminal && !resetRetry) continue
        if(isTerminalCoordinatorStatus(item.status) && mappedTerminal && item.status === mapped.status && !resetRetry) {
            continue
        }

        const applied = applyProgressRecordCoordinatorReconcileActionLocked(state, {
            kind: 'reconcileFromProgressRecord',
            itemKey,
            expectedAttemptId: getAttemptIdFromValue(item),
            expectedAttemptNumber: getAttemptNumberFromValue(item),
            record,
            mapped,
            now,
            resetRetry,
            terminalAtFallback: 'record'
        })
        if(!applied.changed) continue
        if(applied.mappedTerminal) ctx.terminalSettlementHrefs.add(href)
        ctx.changed = true
        ctx.materialized += applied.materialized || 0
        addCoordinatorReconcileAffectedRunIds(ctx, applied.affectedRunIds)
    }

    // A row that settles terminal now archives out of `queue` immediately
    // (archiveTerminalCoordinatorRow), so the loop above -- which only ever
    // sees `queue`'s current rows -- can no longer catch up a resolver-
    // pending settlement that failed to save the first time a row went
    // terminal (e.g. a derived-save failure racing the terminal write).
    // Give the same two settlement checks one more pass over a bounded
    // recent-completed-work window so that self-healing catch-up still
    // happens for rows that already archived. Both settlement functions are
    // side-effect-free no-ops on a row they don't recognize or one that's
    // already settled (they return {changed:false}), so this is safe to
    // run unconditionally on every reconcile tick.
    const recentCompletedRows = await coordinatorQueueReader.completedRecent(50)
    // Keyed copy of the same rows, stashed on ctx so
    // persistCoordinatorReconcileAuthorityTransitionPhase's run-stats
    // recompute (recomputeCoordinatorRuns) can also see recently-archived
    // rows -- otherwise a run's terminalCount undercounts as soon as any of
    // its rows archive out of .queue, defeating this same catch-up pass's
    // own point.
    ctx.recentCompletedRowsByKey = {}
    for(const completedRow of recentCompletedRows) {
        if(!completedRow || typeof completedRow !== 'object') continue
        const completedItemKey = getCoordinatorItemQueueKey(completedRow, '') ||
            getCoordinatorItemHref(completedRow) || ''
        if(!completedItemKey) continue
        ctx.recentCompletedRowsByKey[completedItemKey] = completedRow

        const completedKeyOnlyDerivedMaterialization = materializeTerminalKeyOnlyDerivedStateLocked(state, completedItemKey, completedRow, now)
        if(completedKeyOnlyDerivedMaterialization.changed) {
            ctx.eventsChanged = ctx.eventsChanged || completedKeyOnlyDerivedMaterialization.eventsChanged
            ctx.materialized += completedKeyOnlyDerivedMaterialization.materialized || 0
        }
        addCoordinatorReconcileAffectedRunIds(ctx, completedKeyOnlyDerivedMaterialization.affectedRunIds)

        const terminalResolverPendingSettlement = settleTerminalResolverPendingSourceRecordsLocked(state, completedItemKey, completedRow)
        if(terminalResolverPendingSettlement.changed) {
            ctx.pendingPosts = terminalResolverPendingSettlement.pendingPosts || ctx.pendingPosts
            ctx.pendingPostsChanged = ctx.pendingPostsChanged || terminalResolverPendingSettlement.pendingPostsChanged
            ctx.materialized += terminalResolverPendingSettlement.materialized || 0
        }

        const resolvedResolverPendingSettlement = settleResolvedResolverPendingSourceRecordsLocked(state, completedItemKey, completedRow)
        if(resolvedResolverPendingSettlement.changed) {
            ctx.pendingPosts = resolvedResolverPendingSettlement.pendingPosts || ctx.pendingPosts
            ctx.pendingPostsChanged = ctx.pendingPostsChanged || resolvedResolverPendingSettlement.pendingPostsChanged
            ctx.materialized += resolvedResolverPendingSettlement.materialized || 0
        }
    }

    const runsPauseMaterialized = materializeCoordinatorRunsPausedStateFromControl(
        queue,
        ctx.runs,
        state.stored?.[COORDINATOR_PAUSED_KEY] === true,
        now
    )
    if(runsPauseMaterialized.changed) {
        ctx.runs = runsPauseMaterialized.runs || ctx.runs
        state.runs = ctx.runs
        ctx.runsMetadataChanged = true
        ctx.materialized += runsPauseMaterialized.affectedRunIds.length
        addCoordinatorReconcileAffectedRunIds(ctx, runsPauseMaterialized.affectedRunIds)
    }
}

// 2026-09-29: deliberately NOT migrated onto applyCoordinatorRunsUpdate
// (see that function's comment and mutated-running-total-audit-todo-2026-09-25.md)
// -- this phase already runs entirely inside reconcileCoordinatorStorage's
// own enqueueSpaceFeedStorageUpdate exclusive turn (see
// reconcileCoordinatorStorageLocked's caller), so it isn't actually racing
// concurrent JS execution the way the other ~23 call sites can (most of
// which read `runs` and save it back within their own, unrelated
// enqueueSpaceFeedStorageUpdate turns, or via coordinatorAuthority's
// narrower per-row lock, with no shared exclusion between them). More to
// the point, this phase's runs/events/pendingPosts/nukedPosts all land in
// one combined saveCoordinatorState call alongside a separate queue-WAL
// write -- splitting runs+events out to the locked helper would add a
// second storage write to an already-tuned periodic reconcile pass for a
// race this path isn't actually exposed to. Left as a known, intentional
// exception; revisit only if this phase's write path stops being fully
// enqueueSpaceFeedStorageUpdate-exclusive.
async function persistCoordinatorReconcileAuthorityTransitionPhase(ctx = {}) {
    // Merge in recently-archived rows (see
    // applyCoordinatorReconcileQueueAuthorityTransitionPhase's
    // recentCompletedRowsByKey) so a run's terminalCount/activeCount reflect
    // rows that already left .queue, not just what's still resident.
    // .queue itself takes precedence on any key collision (shouldn't happen
    // in practice -- a row is in exactly one of the two -- but .queue is the
    // live/authoritative side if it ever does).
    const runStatsQueue = ctx.recentCompletedRowsByKey && Object.keys(ctx.recentCompletedRowsByKey).length
        ? {...ctx.recentCompletedRowsByKey, ...ctx.queue}
        : ctx.queue
    const nextRuns = (ctx.recomputeAllRuns || ctx.affectedRunIds.size)
        ? recomputeCoordinatorRuns(runStatsQueue, ctx.runs, ctx.recomputeAllRuns ? null : ctx.affectedRunIds,
            new Set(Object.values(ctx.recentCompletedRowsByKey || {})))
        : ctx.runs
    const runsChanged = (ctx.runsMetadataChanged || nextRuns !== ctx.runs) && JSON.stringify(nextRuns) !== JSON.stringify(ctx.originalRuns)
    const storagePatch = {}

    let progressProjectionSaved = {saved: true, rows: 0}
    let progressProjectionDeleted = {saved: true, rows: 0}
    if(ctx.progressChanged) {
        const prunedProgress = pruneProfileNukeProgress(ctx.progress)
        const changedProgressRecords = getChangedProfileProgressRecords(ctx.originalProgress, prunedProgress)
        const deletedProgressHrefs = Object.keys(ctx.originalProgress || {})
            .filter(href => !Object.prototype.hasOwnProperty.call(prunedProgress, href))
        profileNukeProgress = prunedProgress

        if(Object.keys(changedProgressRecords).length) {
            try {
                progressProjectionSaved = await saveProfileNukeProgressRowProjection(changedProgressRecords, {
                    metricPath: 'reconcile.progressProjection'
                })
            }
            catch(error) {
                progressProjectionSaved = false
                recordCoordinatorDiagnosticEvent(
                    'reconcile-progress-projection-save-failed',
                    error?.message || 'Reconcile progress projection save failed'
                )
            }
        }

        if(deletedProgressHrefs.length) {
            try {
                progressProjectionDeleted = await deleteProfileNukeProgressRowProjection(deletedProgressHrefs, {
                    metricPath: 'reconcile.progressProjectionDelete'
                })
            }
            catch(error) {
                progressProjectionDeleted = false
                recordCoordinatorDiagnosticEvent(
                    'reconcile-progress-projection-delete-failed',
                    error?.message || 'Reconcile progress projection delete failed'
                )
            }

        }
    }
    let saved = true
    if(progressProjectionSaved === false || progressProjectionSaved?.saved === false ||
        progressProjectionDeleted === false || progressProjectionDeleted?.saved === false) {
        saved = false
    }
    let queueAuthorityPersistence = null
    let queueAuthorityChangedRows = 0
    if(ctx.changed) {
        queueAuthorityPersistence = await persistCoordinatorReconcileQueueAuthorityMutation(ctx.originalQueue, {
            ...ctx.state,
            queue: ctx.queue,
            runs: nextRuns
        }, {
            operationKind: 'reconcile-progress',
            prunedRowKeys: ctx.prunedRowKeys || []
        })
        queueAuthorityChangedRows = Number.parseInt(queueAuthorityPersistence?.changedRows, 10) || ctx.materialized
        if(queueAuthorityPersistence?.saved !== true) {
            saved = false
            incrementQueueWakeupMetric('reconcile.queueWalSaveFailed')
            recordCoordinatorDiagnosticEvent(
                'reconcile-queue-wal-save-failed',
                queueAuthorityPersistence?.reason || 'Reconcile queue authority WAL save failed'
            )
            scheduleCoordinatorReconcile(1000, {
                reason: 'reconcile-queue-wal-save-failed',
                edgeTriggered: true
            })
        }
    }
    const queueAuthoritySaved = !ctx.changed || queueAuthorityPersistence?.saved === true
    if(queueAuthoritySaved && runsChanged) storagePatch[COORDINATOR_RUNS_KEY] = nextRuns
    if(queueAuthoritySaved && ctx.eventsChanged) storagePatch[COORDINATOR_EVENTS_KEY] = ctx.events
    if(queueAuthoritySaved && ctx.pendingPostsChanged) storagePatch[SPACE_PENDING_NUKED_POSTS_KEY] = ctx.pendingPosts
    if(queueAuthoritySaved && ctx.nukedPostsChanged) storagePatch[SPACE_NUKED_POSTS_KEY] = ctx.nukedPosts

    if(Object.keys(storagePatch).length) {
        const stateSaved = await saveCoordinatorState({
            runs: storagePatch[COORDINATOR_RUNS_KEY],
            events: storagePatch[COORDINATOR_EVENTS_KEY],
            pendingPosts: storagePatch[SPACE_PENDING_NUKED_POSTS_KEY],
            nukedPosts: storagePatch[SPACE_NUKED_POSTS_KEY]
        }, { metricPath: 'reconcile.authorityTransitionPhase',
            queue: false,
            runs: runsChanged,
            events: ctx.eventsChanged,
            progress: false,
            pendingPosts: ctx.pendingPostsChanged,
            nukedPosts: ctx.nukedPostsChanged,
            reason: 'reconcile',
            queueOperation: 'reconcile-progress',
            queueChangedRows: queueAuthorityChangedRows || ctx.materialized,
            coordinatorAuthorityWrite: ctx.changed && queueAuthorityPersistence?.saved === true
        })
        if(stateSaved === false) saved = false
    }
    if(ctx.terminalSettlementHrefs.size) {
        const terminalSettlementHrefs = Array.from(ctx.terminalSettlementHrefs)
        const terminalSettlementHrefsThisPass = terminalSettlementHrefs.slice(0, COORDINATOR_TERMINAL_SETTLEMENT_CHUNK_SIZE)
        await settleTerminalCoordinatorItemsLocked({
            profileHrefs: terminalSettlementHrefsThisPass
        })
        if(terminalSettlementHrefs.length > terminalSettlementHrefsThisPass.length) {
            incrementQueueWakeupMetric('reconcile.terminalSettlementChunked')
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminal-settlement-remainder',
                edgeTriggered: true
            })
        }
    }
    if(ctx.progressReconcileDeferredKeys.size) {
        // Rows whose tab-status-driven reconcile tail didn't fit in this
        // tick's COORDINATOR_PROGRESS_RECONCILE_CHUNK_SIZE window (see that
        // constant's comment). They're left exactly as-is -- no partial
        // mutation happened for them -- and progressReconcileTailResumeKey
        // already points a follow-up tick's window at wherever this one left
        // off, so a prompt reconcile is enough to keep the rotation moving
        // through the backlog.
        scheduleCoordinatorReconcile(1000, {
            reason: 'progress-reconcile-remainder',
            edgeTriggered: true
        })
    }
    for(const tabId of saved !== false ? ctx.tabsToCloseAfterReconcile : []) {
        detachQueuedTabRuntimeState(tabId, 'storage-reconcile-tab-close')
        try {
            await browser.tabs.remove(tabId)
        }
        catch {}
    }
    await flushPendingCoordinatorDiagnosticEventsIfIdle(getCoordinatorQueueWorkCounts(ctx.queue || {}))

    return {
        materialized: ctx.materialized,
        queueChanged: ctx.changed,
        pendingPostsChanged: ctx.pendingPostsChanged,
        nukedPostsChanged: ctx.nukedPostsChanged,
        runsChanged,
        eventsChanged: ctx.eventsChanged,
        progressChanged: ctx.progressChanged,
        queueCount: Object.keys(ctx.queue).length,
        runCount: Object.keys(nextRuns).length
    }
}

async function reconcileCoordinatorStorageLocked(options = {}) {
    const ctx = await loadCoordinatorReconcileAuthorityPhase(options)
    coordinatorDiagnosticBatchDepth += 1
    try {
        materializeCoordinatorReconcileDerivedProjectionPhase(ctx)
        await reconcileCoordinatorRuntimeActorsPhase(ctx)
        await applyCoordinatorReconcileQueueAuthorityTransitionPhase(ctx)
        return persistCoordinatorReconcileAuthorityTransitionPhase(ctx)
    }
    finally {
        coordinatorDiagnosticBatchDepth = Math.max(0, coordinatorDiagnosticBatchDepth - 1)
    }
}

async function settleTerminalCoordinatorItems(options = {}) {
    return enqueueSpaceFeedStorageUpdate(() => settleTerminalCoordinatorItemsLocked(options), {
        reason: options.storageReason || 'settle-terminal-coordinator-items',
        timeoutMs: options.timeoutMs || QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
    })
}

async function settleTerminalCoordinatorItemsLocked(options = {}) {
    // COORDINATOR_TERMINAL_SETTLEMENT_CHUNK_SIZE's own comment describes this
    // function as "fine for the single-href call sites" -- true for the
    // 'settle-terminal-coordinator-items' runtime-message route's normal
    // per-tab-completion calls, but content.js's space-feed reconciliation
    // (reconcileStaleSpaceFeedProgress / scheduleSpaceFeedProgressReconciliation)
    // sends whatever candidate/pending profile hrefs it currently has for the
    // whole page in one message, unbounded, straight into this function's own
    // per-href await loop below -- bypassing the cap reconcile's own call
    // site already applies to itself. Capping here too closes that gap for
    // every caller at once. No explicit follow-up reschedule is needed for
    // the dropped remainder: content.js already re-sends its still-pending
    // href list on its own periodic reconciliation cadence, and the
    // pendingPosts this call returns will still list anything not settled
    // this pass, so the next natural call picks up right where this one left
    // off.
    const normalizedRequestedHrefs = getNormalizedProfileHrefList(options.profileHrefs || [])
    const requestedHrefs = normalizedRequestedHrefs.slice(0, COORDINATOR_TERMINAL_SETTLEMENT_CHUNK_SIZE)
    if(normalizedRequestedHrefs.length > requestedHrefs.length) {
        incrementQueueWakeupMetric('terminalSettlement.requestedHrefsChunked')
    }

    // The resident state answers (P2): the queue, the runs, the progress and the space post keys. The gate loads it when it is
    // not loaded yet, and a load that fails rejects this settlement (P4). Nothing is read from storage or decoded here.
    const pendingLoad = coordinatorAuthority.ensureHydrated()
    if(pendingLoad) await pendingLoad
    const residentAuthority = coordinatorAuthority.current()
    const stored = coordinatorAuthority.residentStored()
    let queue = residentAuthority.queue || {}
    let currentAuthorityState = {
        stored,
        queue,
        runs: normalizeCoordinatorMap(residentAuthority.runs || stored[COORDINATOR_RUNS_KEY])
    }
    const progress = getProfileNukeProgressRecordsFromProjection(stored, requestedHrefs)
    currentAuthorityState.progress = progress
    let terminalEntries = getCoordinatorTerminalItemEntries(queue, requestedHrefs)
    const terminalProgressSettlementHrefs = requestedHrefs.filter(href => {
        const entry = findCoordinatorQueueEntryForHref(queue, href)
        const item = entry?.item || null
        if(!item || isTerminalCoordinatorStatus(item.status)) return false
        const record = progress[href] || profileNukeProgress?.[href] || null
        if(!record || !isTerminalProfileNukeRecord(record) || hasMismatchedCoordinatorAttempt(item, record)) return false
        return isTerminalCoordinatorStatus(getCoordinatorStatusFromProgress(record).status)
    })
    const missingQueueHrefs = requestedHrefs.filter(href => !findCoordinatorQueueEntryForHref(queue, href))
    const missingConfirmedHrefs = new Set(missingQueueHrefs.filter(href => isSuccessfulProfileNukeRecord(progress[href])))
    const missingClearedHrefs = new Set(missingQueueHrefs.filter(href => !missingConfirmedHrefs.has(href)))
    if(!terminalEntries.length && !terminalProgressSettlementHrefs.length &&
        !missingConfirmedHrefs.size && !missingClearedHrefs.size) {
        scheduleTerminalOwnedProfileTabCleanup(requestedHrefs)
        return {settled: 0, confirmed: 0, cleared: 0, progressRestored: 0, pendingPosts: null, nukedPosts: null}
    }

    const now = Date.now()
    const confirmedHrefs = new Set(missingConfirmedHrefs)
    const clearedHrefs = new Set(missingClearedHrefs)
    let queueChanged = false
    let queueChangedRows = 0
    let progressRestored = 0
    let progressChanged = false
    let terminalProgressSettled = 0
    let terminalProgressSettlementFailed = 0
    let terminalProgressSettlementLastReason = ''
    const progressProjectionRecords = {}

    for(const href of requestedHrefs) {
        const entry = findCoordinatorQueueEntryForHref(queue, href)
        const item = entry?.item || null
        if(!entry?.key || !item || isTerminalCoordinatorStatus(item.status)) continue

        const record = progress[href] || profileNukeProgress?.[href] || null
        if(!record || !isTerminalProfileNukeRecord(record) || hasMismatchedCoordinatorAttempt(item, record)) continue

        const mapped = getCoordinatorStatusFromProgress(record)
        if(!isTerminalCoordinatorStatus(mapped.status)) continue

        const settlementResult = await settleDurableCoordinatorItemFromTerminalProgress(
            entry.key,
            item,
            record,
            {currentAuthorityState}
        ).catch(error => ({
            changed: false,
            reason: 'terminal-progress-settlement-error',
            error: error?.message || `${error || ''}`
        }))

        if(settlementResult?.changed === true) {
            currentAuthorityState = refreshAuthorityStateIfChanged(currentAuthorityState, true)
            queue = currentAuthorityState.queue || queue
            currentAuthorityState.progress = progress
            queueChanged = true
            queueChangedRows += 1
            terminalProgressSettled += 1
            incrementQueueWakeupMetric('terminalSettlement.terminalProgressSettled')
            continue
        }

        terminalProgressSettlementFailed += 1
        terminalProgressSettlementLastReason = settlementResult?.reason || 'unknown'
        incrementQueueWakeupMetric('terminalSettlement.terminalProgressSettlementFailed')
        recordCoordinatorDiagnosticEvent(
            'terminal-progress-settlement-failed',
            settlementResult?.reason || 'Terminal settlement could not settle terminal progress row'
        )
        scheduleCoordinatorReconcile(1000, {
            reason: 'terminal-progress-settlement-failed',
            edgeTriggered: true
        })
    }

    terminalEntries = getCoordinatorTerminalItemEntries(queue, requestedHrefs)

    // Stage every row's mutation in memory first, then persist all of them
    // in a single batched WAL write (matching the pattern already used by
    // mutateCoordinatorStoredWorkCancel) instead of one applyWithinStorageUpdate
    // round-trip per row. There's no genuine inter-row ordering dependency:
    // each row's guard checks (still-terminal, settlement key unchanged
    // since it was read) are pure in-memory comparisons against `item`,
    // which is a stable snapshot already captured before this loop runs and
    // isn't mutated by processing any other row -- the previous per-row
    // persistence only mattered for making change visible to code outside
    // this function, not to later iterations of this same loop, and this
    // whole function only ever runs inside an already-serialized storage
    // update cycle (the "Locked" suffix convention), so nothing else can
    // interleave mid-loop regardless.
    const settlementResults = []
    const settlementHrefsByRowKey = new Map()

    for(const {itemKey, href, item} of terminalEntries) {
        const currentRecord = progress[href] || profileNukeProgress?.[href] || null
        if(shouldRestoreTerminalProgressFromCoordinatorItem(item, currentRecord)) {
            const restoredRecord = makeTerminalProgressRecordFromCoordinatorItem(
                href,
                item,
                currentRecord || {},
                'Restored terminal profile progress during coordinator settlement'
            )
            if(restoredRecord && JSON.stringify(restoredRecord) !== JSON.stringify(currentRecord || {})) {
                progress[href] = restoredRecord
                profileNukeProgress = {
                    ...profileNukeProgress,
                    [href]: restoredRecord
                }
                progressProjectionRecords[href] = restoredRecord
                progressChanged = true
                progressRestored += 1
            }
        }

        const actionKind = getCoordinatorActionKindForItem(item)
        const sourceSettlementOutcome = `${item.status || ''}` === 'succeeded' &&
            actionKind !== UNBLOCK_UNMUTE_ACTION_KIND
            ? 'confirmed'
            : 'cleared'
        const settlementKey = getCoordinatorItemSettlementKey(item)
        if(!settlementKey) continue
        if(item.sourceSettlementKey === settlementKey) {
            if((item.sourceSettlementOutcome || sourceSettlementOutcome) === 'confirmed') {
                confirmedHrefs.add(href)
            }
            else {
                clearedHrefs.add(href)
            }
            continue
        }

        if(sourceSettlementOutcome === 'confirmed') {
            confirmedHrefs.add(href)
        }
        else {
            clearedHrefs.add(href)
        }

        const nextItem = {
            ...item,
            sourceSettledAt: now,
            sourceSettlementKey: settlementKey,
            sourceSettlementOutcome
        }
        settlementHrefsByRowKey.set(itemKey, href)
        settlementResults.push(makeCoordinatorAuthorityApplyResult({
            operationKind: 'terminal-settlement',
            rowKey: itemKey,
            reason: 'ordinaryMutation'
        }, {
            accepted: true,
            changed: true,
            durable: true,
            reason: 'persisted',
            previousRow: item,
            nextRow: nextItem,
            terminal: true
        }))
    }

    if(settlementResults.length) {
        let settlementPersistence = null
        try {
            settlementPersistence = await coordinatorAuthority.persistCoordinator(
                {results: settlementResults},
                {
                    operationKind: 'terminal-settlement',
                    reason: 'ordinaryMutation',
                    metricPath: 'terminalSettlement.save.queueWal',
                    projectionMetricPath: 'terminalSettlement.save.projection'
                }
            )
        }
        catch(error) {
            settlementPersistence = {
                saved: false,
                reason: 'persistence-error',
                error: `${error?.message || error || 'storage error'}`.slice(0, 240)
            }
        }

        if(settlementPersistence?.saved === true) {
            currentAuthorityState = coordinatorAuthority.current()
            queue = currentAuthorityState.queue
            queueChanged = true
            queueChangedRows += settlementResults.length
        }
        else {
            for(const href of settlementHrefsByRowKey.values()) {
                confirmedHrefs.delete(href)
                clearedHrefs.delete(href)
            }
            incrementQueueWakeupMetric('terminalSettlement.authorityApplyFailed')
            recordCoordinatorDiagnosticEvent(
                'terminal-settlement-authority-apply-failed',
                settlementPersistence?.reason || 'Terminal settlement authority mutation failed'
            )
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminal-settlement-authority-apply-failed',
                edgeTriggered: true
            })
            // The single-row applyWithinStorageUpdate path this replaced
            // read/wrote through coordinatorAuthority directly, which
            // synced its resident cache even on a failed attempt. Batching
            // bypasses that for the (now single) attempt, so hydrate
            // explicitly here too -- otherwise coordinatorAuthority.current()
            // can report stale/empty state after a failed settlement batch.
            await coordinatorAuthority.hydrate().catch(() => null)
        }
    }

    if(!confirmedHrefs.size && !clearedHrefs.size && !queueChanged && !progressChanged) {
        scheduleTerminalOwnedProfileTabCleanup(terminalEntries.map(entry => entry.href))
        return {settled: 0, confirmed: 0, cleared: 0, progressRestored: 0, terminalProgressSettled, terminalProgressSettlementFailed, terminalProgressSettlementLastReason, pendingPosts: null, nukedPosts: null}
    }

    const derivedSettlement = buildTerminalCoordinatorSettlementDerivedPayload(stored, progress, {
        confirmedHrefs,
        clearedHrefs,
        progressChanged,
        progressRecords: progressProjectionRecords
    })
    const payload = derivedSettlement.payload

    if(progressChanged || Object.keys(payload).length) {
        let derivedSaved = true
        if(progressChanged) {
            let progressProjectionSaved = false
            try {
                progressProjectionSaved = await saveProfileNukeProgressRowProjection(
                    derivedSettlement.progressRecords,
                    {metricPath: 'terminalSettlement.derived.progressProjection'}
                )
            }
            catch(error) {
                progressProjectionSaved = false
                recordCoordinatorDiagnosticEvent(
                    'terminal-settlement-progress-projection-save-failed',
                    error?.message || 'Terminal settlement progress projection save failed'
                )
            }
            if(progressProjectionSaved === false || progressProjectionSaved?.saved === false) {
                derivedSaved = false
            }
        }
        if(Object.keys(payload).length) {
            let materializedSaved = false
            try {
                materializedSaved = (await coordinatorAuthority.persistCoordinator({stored: payload}, {
                    storageOptions: {
                        snapshotWriteReason: 'ordinaryMutation',
                        metricPath: 'terminalSettlement.derived.save',
                        queueOperation: 'terminal-settlement-derived',
                        queueChangedRows: 0
                    }
                })).saved
            }
            catch(error) {
                materializedSaved = false
                recordCoordinatorDiagnosticEvent(
                    'terminal-settlement-derived-save-failed',
                    error?.message || 'Terminal settlement derived save failed'
                )
            }
            if(materializedSaved === false) {
                derivedSaved = false
            }
        }
        if(derivedSaved === false) {
            incrementQueueWakeupMetric('terminalSettlement.derivedSaveFailed')
            scheduleCoordinatorReconcile(1000, {
                reason: 'terminal-settlement-derived-save-failed',
                edgeTriggered: true
            })
        }
    }

    scheduleTerminalOwnedProfileTabCleanup(terminalEntries.map(entry => entry.href))

    return {
        settled: confirmedHrefs.size + clearedHrefs.size,
        confirmed: confirmedHrefs.size,
        cleared: clearedHrefs.size,
        progressRestored,
        pendingPosts: derivedSettlement.pendingPosts,
        nukedPosts: derivedSettlement.nukedPosts
    }
}

async function rememberCoordinatorTabId(tabId) {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId) return

    coordinatorTabId = normalizedTabId
    // Owner 18 Oct: the same id was written on every call (124 writes in one run). Write only when it changes, and do not hold the
    // caller on the write, so the write never adds to the time the caller spends on the authority lane.
    if(coordinatorTabIdSavedToStorage === normalizedTabId) return
    metricStorageSet({[COORDINATOR_TAB_KEY]: normalizedTabId}, {
        snapshotWriteReason: 'userMemoryNonAuthority'
    }).then(saved => {
        if(saved !== false) coordinatorTabIdSavedToStorage = normalizedTabId
    }, () => null)
}

async function forgetCoordinatorTabId(tabId = null) {
    const normalizedTabId = normalizeTabId(tabId)
    if(normalizedTabId && coordinatorTabId && normalizedTabId !== coordinatorTabId) return

    coordinatorTabId = null
    coordinatorTabIdSavedToStorage = null
    try {
        await coordinatorStorageAdapter.remove(COORDINATOR_TAB_KEY)
    }
    catch {}
}

async function forgetRemovedCoordinatorTabId(tabId) {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId) return

    if(coordinatorTabId === normalizedTabId) {
        await forgetCoordinatorTabId(normalizedTabId)
        return
    }

    try {
        const stored = await metricStorageGet({[COORDINATOR_TAB_KEY]: null})
        if(normalizeTabId(stored[COORDINATOR_TAB_KEY]) === normalizedTabId) {
            await forgetCoordinatorTabId(normalizedTabId)
        }
    }
    catch {}
}

async function getStoredCoordinatorTabId() {
    if(coordinatorTabId) return coordinatorTabId

    try {
        const stored = await metricStorageGet({[COORDINATOR_TAB_KEY]: null})
        coordinatorTabId = normalizeTabId(stored[COORDINATOR_TAB_KEY])
    }
    catch {
        coordinatorTabId = null
    }

    return coordinatorTabId
}

async function getKnownCoordinatorTab(tabId) {
    const normalizedTabId = normalizeTabId(tabId)
    if(!normalizedTabId) return null

    try {
        const tab = await browser.tabs.get(normalizedTabId)
        // Unlike dedupeCoordinatorTabsOnce's own tabs.query results, a tab
        // fetched directly by id here was never filtered by hash at all --
        // if the worker window (or a #history tab) is the only
        // coordinator.html tab open when it pings the service worker (e.g.
        // announceCoordinatorPageReady's 'coordinator-page-ready' message),
        // this used to happily remember that tab as coordinatorTabId, the
        // singleton "the dashboard tab" tracking every other coordinator
        // tab-open call trusts. Confirmed live 2026-09-29: this corrupted
        // coordinatorTabId to point at the worker window, so opening the
        // real dashboard later reused (and, after the expectedUrl fix,
        // navigated) the worker window's own anchor tab instead of a real
        // dashboard tab.
        if(`${tab?.url || ''}`.includes('#')) return null
        await rememberCoordinatorTabId(normalizedTabId)
        return {
            tabId: normalizedTabId,
            windowId: tab?.windowId || null,
            reused: true,
            closedDuplicates: 0
        }
    }
    catch {
        if(!coordinatorTabId || coordinatorTabId === normalizedTabId) {
            await forgetCoordinatorTabId(normalizedTabId)
        }
        return null
    }
}

async function dedupeCoordinatorTabsOnce(preferredTabId = null) {
    const coordinatorUrl = getCoordinatorPageUrl()
    let matches = []

    try {
        matches = await browser.tabs.query({url: coordinatorUrl})
    }
    catch {
        return null
    }

    // tabs.query's url filter matches by match-pattern (scheme+host+path),
    // which ignores the fragment -- so a plain coordinator.html query also
    // matches the worker window's own anchor tab (coordinator.html#worker-
    // window) AND a #history tab. Confirmed live 2026-09-29: with no
    // separate dashboard tab open, this treated the worker window's tab (or
    // a #history tab) as "the" coordinator tab to keep/reuse, so the
    // popup's Dashboard button either refocused the deliberately-hidden
    // worker window, or reused a #history tab without navigating it back to
    // the plain dashboard URL -- and worse, if some other tab won the
    // "keep" race, this function's own duplicate-cleanup below would call
    // browser.tabs.remove on the worker window's anchor tab, closing it
    // outright. Exclude every hash variant here, not just the worker
    // window's -- this function's job is specifically "the plain dashboard
    // tab", and every other coordinator.html view has its own dedicated
    // open function (openCoordinatorHistoryPage) that doesn't call this one.
    const liveMatches = matches.filter(tab => tab?.id && !`${tab.url || ''}`.includes('#'))
    if(!liveMatches.length) {
        const preferred = await getKnownCoordinatorTab(preferredTabId)
        if(preferred?.tabId) return preferred

        const remembered = await getKnownCoordinatorTab(await getStoredCoordinatorTabId())
        if(remembered?.tabId) return remembered

        await forgetCoordinatorTabId()
        return null
    }

    const keep = liveMatches.find(tab => tab.id === coordinatorTabId) ||
        liveMatches.find(tab => tab.id === preferredTabId) ||
        liveMatches[0]
    const duplicates = liveMatches.filter(tab => tab.id !== keep.id)

    coordinatorTabId = keep.id
    await rememberCoordinatorTabId(keep.id)

    await Promise.allSettled(duplicates.map(tab => browser.tabs.remove(tab.id)))

    return {
        tabId: keep.id,
        windowId: keep.windowId || null,
        reused: true,
        closedDuplicates: duplicates.length
    }
}

async function openCoordinatorPage(options = {}) {
    if(coordinatorOpenPromise) return coordinatorOpenPromise

    coordinatorOpenPromise = openCoordinatorPageOnce(options)
        .finally(() => {
            coordinatorOpenPromise = null
        })

    return coordinatorOpenPromise
}

async function restoreCoordinatorPageForPersistentRetry() {
    try {
        const stored = await metricStorageGet({
            [COORDINATOR_RETRY_FAILED_ENABLED_KEY]: false
        })
        if(stored[COORDINATOR_RETRY_FAILED_ENABLED_KEY]) {
            await ensurePersistentFailedRetryAlarm()
            schedulePersistentFailedRetry(0)
            return {scheduled: true}
        }
        clearPersistentFailedRetry()
        return {scheduled: false}
    }
    catch(error) {
        console.info('Mute Block coordinator retry restore skipped', error)
        return {scheduled: false, reason: 'restore-error'}
    }
}

// persistentRetryExecutorTimers is constructed here, in place at this
// cluster's old source-text position (decomposition Slice 22) -- no
// already-extracted module eagerly references any of its five exported
// names at its own construction site. clearPersistentFailedRetryAlarm and
// runPersistentFailedRetryTick are plain hoisted `async function`
// declarations further below in this file (out of scope, part of the
// async orchestration layer) -- hoisted declarations are visible
// throughout their enclosing scope regardless of textual position, so no
// thunk is needed. See swPersistentRetryExecutorTimers.js's header comment
// for the Promise-chain realm-crossing note covering
// resetCoordinatorExecutorStartPromiseAfterTimeout/
// clearStaleCoordinatorExecutorStartPromise's Promise.resolve() handling
// (that pair's old function bodies, further below at their original
// source-text position, were removed the same way).
const persistentRetryExecutorTimers = createPersistentRetryExecutorTimers({
    now: () => Date.now(),
    setTimeoutFn: setTimeout,
    clearTimeoutFn: clearTimeout,
    constants: {
        PERSISTENT_FAILED_RETRY_INTERVAL_MS,
        COORDINATOR_IDLE_EXECUTOR_START_PROMISE_STALE_MS
    },
    handlers: {
        clearPersistentFailedRetryAlarm,
        runPersistentFailedRetryTick,
        isExecutorRuntimeIdleForPromiseLatch,
        incrementQueueWakeupMetric,
        recordCoordinatorDiagnosticEvent
    },
    state: {
        getCoordinatorExecutorStartPromiseStartedAt: () => coordinatorExecutorStartPromiseStartedAt,
        resetCoordinatorExecutorStartPromise: (reason = 'executor-start-reset') => {
            // Every reset supersedes the enqueue at the head: its token is cancelled, so it stops before its next write.
            // A live head also keeps the reset's reason and its age on the token, so the enqueue that stops can record the
            // supersession with the phase it stopped in, and the next opened tab can time it (review-2 stall measurement).
            const headToken = coordinatorExecutorStartToken
            if(headToken && !headToken.cancelled) {
                const supersededAt = Date.now()
                headToken.supersession = {
                    reason: `${reason || 'executor-start-reset'}`,
                    headAgeMs: coordinatorExecutorStartPromiseStartedAt ? Math.max(0, supersededAt - coordinatorExecutorStartPromiseStartedAt) : 0,
                    supersededAt,
                    recorded: false
                }
                armExecutorStartSupersessionFirstTab(headToken.supersession.reason, supersededAt)
            }
            cancelCoordinatorCancelToken(headToken, reason || 'executor-start-reset')
            coordinatorExecutorStartToken = null
            coordinatorExecutorStartPromise = Promise.resolve()
            coordinatorExecutorStartPromiseStartedAt = 0
        }
    }
})
const {
    clearPersistentFailedRetryTimeout,
    clearPersistentFailedRetry,
    schedulePersistentFailedRetry,
    resetCoordinatorExecutorStartPromiseAfterTimeout,
    clearStaleCoordinatorExecutorStartPromise
} = persistentRetryExecutorTimers

async function ensurePersistentFailedRetryAlarm() {
    if(!browser.alarms?.create) return false

    try {
        await browser.alarms.create(PERSISTENT_FAILED_RETRY_ALARM_NAME, {
            delayInMinutes: PERSISTENT_FAILED_RETRY_ALARM_PERIOD_MINUTES,
            periodInMinutes: PERSISTENT_FAILED_RETRY_ALARM_PERIOD_MINUTES
        })
        return true
    }
    catch {
        return false
    }
}

async function clearPersistentFailedRetryAlarm() {
    if(!browser.alarms?.clear) return false

    try {
        return await browser.alarms.clear(PERSISTENT_FAILED_RETRY_ALARM_NAME)
    }
    catch {
        return false
    }
}

async function runPersistentFailedRetryTick() {
    if(persistentRetryFailedPromise) return persistentRetryFailedPromise

    persistentRetryFailedPromise = (async () => {
        const stored = await metricStorageGet({
            [COORDINATOR_RETRY_FAILED_ENABLED_KEY]: false
        })
        if(!stored[COORDINATOR_RETRY_FAILED_ENABLED_KEY]) {
            clearPersistentFailedRetry()
            return {queued: 0, reason: 'disabled'}
        }

        const result = await retryCoordinatorFailedItems({
            maxItems: 1,
            retryLimit: SOFT_FAIL_RETRY_LIMIT
        }, {})

        const latest = await metricStorageGet({
            [COORDINATOR_RETRY_FAILED_ENABLED_KEY]: false
        })
        if(latest[COORDINATOR_RETRY_FAILED_ENABLED_KEY]) {
            await ensurePersistentFailedRetryAlarm()
            schedulePersistentFailedRetry(PERSISTENT_FAILED_RETRY_INTERVAL_MS)
        }

        return result
    })()
        .catch(error => {
            console.info('Mute Block persistent retry tick skipped', error)
            schedulePersistentFailedRetry(PERSISTENT_FAILED_RETRY_INTERVAL_MS)
            return {queued: 0, reason: 'retry-error'}
        })
        .finally(() => {
            persistentRetryFailedPromise = null
        })

    return persistentRetryFailedPromise
}

async function restoreCoordinatorPageForStoredWork(options = {}) {
    if(coordinatorStoredWorkRestorePromise) return coordinatorStoredWorkRestorePromise

    coordinatorStoredWorkRestorePromise = promiseWithTimeout(
        restoreCoordinatorPageForStoredWorkOnce(options),
        COORDINATOR_STORED_WORK_RESTORE_TIMEOUT_MS,
        'coordinator stored-work restore'
    )
        .catch(error => ({
            restored: false,
            reason: 'restore-timeout',
            timedOut: /timed out/i.test(error?.message || ''),
            error: error?.message || `${error || ''}`
        }))
        .finally(() => {
            coordinatorStoredWorkRestorePromise = null
        })

    return coordinatorStoredWorkRestorePromise
}

async function restoreCoordinatorPageForStoredWorkOnce(options = {}) {
    try {
        const recovery = await recoverStoredCoordinatorWork('coordinator-page-restore', {
            skipStoredWorkCheck: true
        })
        if(!recovery?.hasWork) {
            return {restored: false, reason: recovery?.reason || 'no-stored-work', recovery}
        }
        const coordinator = options.openDisplay === true
            ? await openCoordinatorPage({
                windowId: options.windowId || null
            }).catch(error => ({
                restored: false,
                reason: 'coordinator-open-error',
                error: error?.message || `${error || ''}`
            }))
            : null
        return {
            restored: recovery?.recovered === true,
            coordinator,
            coordinatorOpened: !!coordinator?.tabId,
            serviceWorkerRecoveryFirst: true,
            recovery
        }
    }
    catch(error) {
        console.info('Mute Block coordinator stored-work restore skipped', error)
        return {restored: false, reason: 'restore-error'}
    }
}

async function openCoordinatorPageOnce(options = {}) {
    const coordinatorUrl = getCoordinatorPageUrl()
    const activateOptions = {...options, expectedUrl: coordinatorUrl}
    const existing = await dedupeCoordinatorTabs(coordinatorTabId)
    if(existing?.tabId) return maybeActivateCoordinatorTab(existing, activateOptions)

    const remembered = await getKnownCoordinatorTab(await getStoredCoordinatorTabId())
    if(remembered?.tabId) return maybeActivateCoordinatorTab(remembered, activateOptions)

    if(coordinatorTabId) {
        try {
            const tab = await browser.tabs.get(coordinatorTabId)
            if(!tab?.url || tab.url === coordinatorUrl) {
                await rememberCoordinatorTabId(tab.id)
                return maybeActivateCoordinatorTab({tabId: tab.id, windowId: tab.windowId || null, reused: true}, activateOptions)
            }
        }
        catch {
            await forgetCoordinatorTabId(coordinatorTabId)
        }
    }

    const createOptions = {
        url: coordinatorUrl,
        active: options.active === true
    }
    if(options.windowId) {
        createOptions.windowId = options.windowId
    }

    try {
        const tab = await browser.tabs.create(createOptions)
        await rememberCoordinatorTabId(tab.id)
        const deduped = await dedupeCoordinatorTabs(tab.id)
        return deduped ? {...deduped, reused: false} : {tabId: tab.id, windowId: tab.windowId || null, reused: false}
    }
    catch(error) {
        if(!createOptions.windowId) throw error
        const tab = await browser.tabs.create({
            url: coordinatorUrl,
            active: options.active === true
        })
        await rememberCoordinatorTabId(tab.id)
        const deduped = await dedupeCoordinatorTabs(tab.id)
        return deduped ? {...deduped, reused: false} : {tabId: tab.id, windowId: tab.windowId || null, reused: false}
    }
}

// Deliberately independent of openCoordinatorPage/dedupeCoordinatorTabs and
// the coordinatorTabId singleton those use -- that machinery exists to
// enforce exactly one dashboard tab (with its own remembered-tab-id storage
// and cross-window move-on-request behavior). A history viewer doesn't need
// that guarantee; a simple "reuse if one's already open in this window,
// otherwise open one" is enough and avoids adding a second consumer to the
// dashboard's singleton-tracking state.
let coordinatorHistoryOpenPromise = null

async function openCoordinatorHistoryPage(options = {}) {
    if(coordinatorHistoryOpenPromise) return coordinatorHistoryOpenPromise

    coordinatorHistoryOpenPromise = openCoordinatorHistoryPageOnce(options)
        .finally(() => {
            coordinatorHistoryOpenPromise = null
        })

    return coordinatorHistoryOpenPromise
}

async function openCoordinatorHistoryPageOnce(options = {}) {
    const historyUrl = getCoordinatorHistoryPageUrl()
    const requestedWindowId = Number.parseInt(options.windowId, 10) || 0

    let matches = []
    try {
        matches = await browser.tabs.query({url: getCoordinatorPageUrl()})
    }
    catch {
        matches = []
    }
    // Same tabs.query hash-blindness as dedupeCoordinatorTabsOnce -- filter
    // down to tabs whose actual URL is this exact history view.
    const existing = matches.find(tab => tab?.id && `${tab.url || ''}`.endsWith(COORDINATOR_HISTORY_HASH))
    if(existing?.id) {
        return maybeActivateCoordinatorTab({tabId: existing.id, windowId: existing.windowId || null}, {...options, expectedUrl: historyUrl})
    }

    const createOptions = {
        url: historyUrl,
        active: options.active === true
    }
    if(requestedWindowId) createOptions.windowId = requestedWindowId

    const tab = await browser.tabs.create(createOptions).catch(async () => {
        if(!requestedWindowId) throw new Error('coordinator-history-tab-create-failed')
        return browser.tabs.create({url: historyUrl, active: options.active === true})
    })
    return {tabId: tab.id, windowId: tab.windowId || null, reused: false}
}

async function maybeActivateCoordinatorTab(coordinator = {}, options = {}) {
    if(options.active === true && coordinator?.tabId) {
        // 2026-09-29: the existing coordinator tab can live in a different
        // window than the one this request came from (e.g. the popup's own
        // window) -- previously this just activated it in place and pulled
        // OS focus to whatever window it happened to be in, which reads as
        // "the Dashboard button did nothing" from the window the user
        // actually clicked it in. Move it to the requesting window first so
        // "open the dashboard" always surfaces where it was pressed, rather
        // than yanking focus to wherever a stale dashboard tab was left.
        const requestedWindowId = Number.parseInt(options.windowId, 10) || 0
        if(requestedWindowId && normalizeTabId(coordinator.windowId) !== requestedWindowId) {
            const moved = await browser.tabs.move(coordinator.tabId, {windowId: requestedWindowId, index: -1}).catch(() => null)
            if(moved?.windowId) coordinator = {...coordinator, windowId: moved.windowId}
        }
        // options.expectedUrl guards against reusing a tab that's actually
        // sitting on a different coordinator.html view (a stale #history or
        // #progress hash from earlier navigation) -- a hash-only
        // navigation like this doesn't reload the document, so
        // coordinator.js's own view-mode switch (applyCoordinatorViewMode)
        // needs its hashchange listener to notice and re-render; this makes
        // sure that navigation, and thus the event, actually happens instead
        // of just re-activating the tab in place with stale content still
        // showing. Confirmed live 2026-09-29.
        const updatePayload = {active: true}
        if(options.expectedUrl) updatePayload.url = options.expectedUrl
        const tab = await browser.tabs.update(coordinator.tabId, updatePayload).catch(() => null)
        const windowId = tab?.windowId || coordinator.windowId || null
        if(windowId) {
            await browser.windows?.update?.(windowId, {focused: true}).catch(() => {})
        }
    }

    return coordinator
}

// Cancellation token for the enqueue and fill loops (review-2 S2-1, S2-2, S5-1). A token is a flag plus the reason it was
// cancelled. Cancelling never throws and never awaits. A loop that owns a token checks it synchronously, at the points
// where it would claim, reserve or write, and stops there. A timeout or a reset is what cancels one.
function createCoordinatorCancelToken(label = '') {
    return {label: `${label || ''}`, cancelled: false, reason: ''}
}

function cancelCoordinatorCancelToken(token = null, reason = '') {
    if(!token || token.cancelled) return false
    token.cancelled = true
    token.reason = `${reason || ''}`.trim()
    return true
}

// What a superseded enqueue returns: the same shape as a normal return, marked `superseded`, with nothing planned and no fill run.
// The apply pass returns at once on the marker and touches no row. Classified as a failed enqueue, the empty result would charge
// a retry to rows that the enqueue replacing this one is opening (review-2 follow-up).
function supersededExecutorEnqueueResult() {
    return {superseded: true, reason: 'executor-start-superseded', queued: 0, queuedKeys: [], terminalizedExhausted: 0, terminalizedExhaustedKeys: [], fillResult: null}
}

// Supersession measurement (review-2 stall follow-up, owner accepted: measure before any rule change). Two measurements, each with
// bounded state. Per superseded enqueue, the phase it stopped in ('start', 'before-fill' or 'after-fill'), recorded once when it
// stops. Per reset of a live head, the time until the next queued tab opens, timed from the reset. Both feed the queue wakeup
// metrics and the coordinator diagnostics, so the rate can be read before the latch rule is chosen.
let pendingExecutorStartSupersessionFirstTab = null

function armExecutorStartSupersessionFirstTab(reason = '', supersededAt = Date.now()) {
    if(pendingExecutorStartSupersessionFirstTab) finishExecutorStartSupersessionFirstTab(null)
    pendingExecutorStartSupersessionFirstTab = {reason: `${reason || ''}`, supersededAt}
}

function finishExecutorStartSupersessionFirstTab(timeToFirstTabMs = null) {
    const pending = pendingExecutorStartSupersessionFirstTab
    if(!pending) return false
    pendingExecutorStartSupersessionFirstTab = null
    incrementQueueWakeupMetric(timeToFirstTabMs === null
        ? 'pump.executorStartSupersededNoTab'
        : 'pump.executorStartSupersededFirstTab')
    recordCoordinatorDiagnosticEvent('executor-start-superseded-first-tab', pending.reason, {
        reason: pending.reason,
        timeToFirstTabMs
    })
    return true
}

// Called where a queued tab opens. Only the first tab after a reset is timed; any enqueue's tab counts.
function noteExecutorStartSupersessionFirstTab() {
    const pending = pendingExecutorStartSupersessionFirstTab
    if(!pending) return false
    return finishExecutorStartSupersessionFirstTab(Math.max(0, Date.now() - pending.supersededAt))
}

// Called by a superseded enqueue as it stops. Each enqueue is recorded once.
function recordExecutorStartSupersession(cancelToken = null, phase = '') {
    const supersession = cancelToken?.supersession
    if(!supersession || supersession.recorded) return false
    supersession.recorded = true
    const stoppedPhase = `${phase || 'unknown'}`
    incrementQueueWakeupMetric(`pump.executorStartSuperseded.${stoppedPhase}`)
    recordCoordinatorDiagnosticEvent('executor-start-superseded', supersession.reason, {
        phase: stoppedPhase,
        reason: supersession.reason,
        headAgeMs: supersession.headAgeMs
    })
    return true
}

async function enqueueExistingExecutorForCoordinator(items = [], coordinator = {}, options = {}) {
    clearStaleCoordinatorExecutorStartPromise(`${options.reason || 'executor-start'}-before-chain`)

    const startedAt = Date.now()
    if(coordinatorExecutorStartPromiseStartedAt) {
        const ageMs = Date.now() - coordinatorExecutorStartPromiseStartedAt
        const detachedLatch = isExecutorRuntimeDetachedForPromiseLatch()
        const pendingCount = Array.isArray(items) ? items.length : 0
        const runtimeSurfaceEmpty = queueRuntime.getActiveQueuedTabCount() <= 0 &&
            queueRuntime.getPendingTabActionCount() <= 0
        if((detachedLatch || runtimeSurfaceEmpty) &&
            pendingCount > 0 &&
            ageMs >= COORDINATOR_DETACHED_EXECUTOR_START_PROMISE_STALE_MS) {
            resetCoordinatorExecutorStartPromiseAfterTimeout(detachedLatch
                ? 'executor-start-detached-latch-reset'
                : 'executor-start-empty-runtime-latch-reset')
        }
        else {
            incrementQueueWakeupMetric('pump.executorStartPromiseCoalesced')
            scheduleCoordinatorQueueResume(1000, 'executor-start-in-flight-coalesced', {
                allowBeforeQuora: true
            })
            return {
                queued: 0,
                terminalizedExhausted: 0,
                queuedKeys: [],
                terminalizedExhaustedKeys: [],
                coalesced: true,
                pending: pendingCount,
                reason: 'executor-start-in-flight-coalesced',
                executorStartPromiseAgeMs: ageMs,
                executorStartPromiseDetached: detachedLatch
            }
        }
    }
    const previousPromise = coordinatorExecutorStartPromise
    const token = options.cancelToken || createCoordinatorCancelToken('executor-start')
    const nextPromise = previousPromise
        .catch(() => {})
        .then(() => enqueueExistingExecutorForCoordinatorOnce(items, coordinator, {...options, cancelToken: token}))
    coordinatorExecutorStartPromiseStartedAt = coordinatorExecutorStartPromiseStartedAt || startedAt
    const trackedPromise = nextPromise.finally(() => {
        if(coordinatorExecutorStartPromise === trackedPromise) {
            coordinatorExecutorStartPromiseStartedAt = 0
            coordinatorExecutorStartToken = null
        }
    })
    coordinatorExecutorStartPromise = trackedPromise
    coordinatorExecutorStartToken = token

    return coordinatorExecutorStartPromise
}

async function getRecoverableLiveTabForQueuedRuntimeAction(action = {}, entry = {}, options = {}) {
    const item = entry.item || null
    const itemKey = entry.key || entry.href || ''
    if(!item || `${item.status || ''}`.trim() !== 'queued') {
        return {tab: null, deferred: false, reason: 'queued-runtime-action-not-durable-queued'}
    }

    const liveProfileTabsByHref = options.liveProfileTabsByHref || await getLiveProfileTabsByHref().catch(() => new Map())
    const progress = options.currentAuthorityState?.progress || coordinatorAuthority.current()?.progress || {}
    const record = getCoordinatorProgressRecordForItem(itemKey, item, progress)
    const safeTab = getLiveTabForCoordinatorItem(item, itemKey, liveProfileTabsByHref, record) ||
        getLiveProfileTabForRolledBackQueuedCoordinatorReclaim(item, record, itemKey, liveProfileTabsByHref) ||
        await getWorkerSurfaceLiveTabForQueuedCoordinatorItem(item, itemKey, liveProfileTabsByHref, record)
    if(safeTab) {
        return {
            tab: safeTab,
            deferred: false,
            reason: 'queued-runtime-action-live-tab-adoptable',
            liveProfileTabsByHref,
            record
        }
    }

    const href = entry.href || getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey)
    const liveTabs = getLiveTabsForProfileHref(liveProfileTabsByHref, href)
        .filter(tab => normalizeTabId(tab?.id))
    if(liveTabs.length) {
        const actionTabId = normalizeTabId(action?.tabId || action?.createdTabId || action?.targetTabId || null)
        const hasRuntimeEvidence = !!actionTabId ||
            (Number.parseInt(action?.openedAt, 10) || 0) > 0 ||
            (Number.parseInt(action?.liveTabAdoptedAt, 10) || 0) > 0 ||
            `${action?.actionSurfaceMode || ''}`.trim() === 'worker-window' ||
            !!Number.parseInt(action?.actionSurfaceWindowId, 10)
        return {
            tab: null,
            deferred: hasRuntimeEvidence,
            reason: hasRuntimeEvidence
                ? 'queued-runtime-action-live-tab-needs-reconcile'
                : 'queued-runtime-action-no-safe-live-tab',
            liveProfileTabs: liveTabs.length,
            liveProfileTabsByHref,
            record
        }
    }

    return {
        tab: null,
        deferred: false,
        reason: 'queued-runtime-action-no-live-tab',
        liveProfileTabsByHref,
        record
    }
}

async function recoverQueuedRuntimeActionsAfterExecutorEnqueueTimeout(ownerTabId = null, options = {}) {
    if(!queueRuntime.getActivationIntentCount()) {
        let fillPromiseCleared = false
        if(queuedTabFillPromise && isExecutorRuntimeIdleForPromiseLatch()) {
            resetQueuedTabFillState()
            fillPromiseCleared = true
            incrementQueueWakeupMetric('pump.changed.clearedExecutorTimeoutIdleFillPromise')
            recordCoordinatorDiagnosticEvent(
                'coordinator-executor-timeout-idle-fill-promise-cleared',
                'Cleared idle queued-tab fill promise after executor enqueue timeout with no runtime actions'
            )
            scheduleQueuedWorkContinuation(options.reason || 'coordinator-executor-enqueue-timeout')
        }
        return {
            changed: fillPromiseCleared,
            adopted: 0,
            preserved: 0,
            deferred: 0,
            fillPromiseCleared,
            keys: [],
            reason: fillPromiseCleared
                ? 'coordinator-executor-enqueue-timeout-idle-fill-promise-cleared'
                : 'no-timeout-runtime-actions-to-recover'
        }
    }

    let currentAuthorityState = options.currentAuthorityState || coordinatorAuthority.current() || null
    let liveProfileTabsByHref = options.liveProfileTabsByHref || null
    const keys = []
    let adopted = 0
    let preserved = 0
    let pruned = 0
    let deferred = 0
    for(let index = queueRuntime.getActivationIntentCount() - 1; index >= 0; index -= 1) {
        const action = queueRuntime.getActivationIntentAt(index)
        const actionOwnerTabId = action?.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID
        if(ownerTabId && actionOwnerTabId !== ownerTabId) continue

        const entry = getQueuedRuntimeActionAuthorityEntry(action, currentAuthorityState)
        const item = entry.item || null
        if(`${item?.status || ''}`.trim() !== 'queued') continue
        if(queuedRuntimeActionHasActiveOrPendingSurface(action)) {
            preserved += 1
            keys.push(entry.href || entry.key)
            continue
        }

        if(!liveProfileTabsByHref) {
            liveProfileTabsByHref = await getLiveProfileTabsByHref().catch(() => new Map())
        }
        const recovery = await getRecoverableLiveTabForQueuedRuntimeAction(action, entry, {
            currentAuthorityState,
            liveProfileTabsByHref
        })
        if(recovery.liveProfileTabsByHref) liveProfileTabsByHref = recovery.liveProfileTabsByHref
        if(recovery.tab) {
            const adoptedLiveTab = await adoptLiveCoordinatorQueuedTab(
                item,
                entry.key || entry.href,
                recovery.tab,
                actionOwnerTabId,
                {currentAuthorityState}
            ).catch(() => false)
            if(adoptedLiveTab) {
                queueRuntime.dropRuntimeActionAt(index)
                adopted += 1
                keys.push(entry.href || entry.key)
                currentAuthorityState = refreshAuthorityStateIfChanged(currentAuthorityState, true)
                continue
            }
        }

        if(recovery.deferred === true) {
            preserved += 1
            deferred += 1
        }
        else {
            queueRuntime.dropRuntimeActionAt(index)
            pruned += 1
        }
        keys.push(entry.href || entry.key)
    }

    let fillPromiseCleared = false
    if(adopted + preserved + pruned > 0) {
        if(queuedTabFillPromise) {
            resetQueuedTabFillState()
            fillPromiseCleared = true
            incrementQueueWakeupMetric('pump.changed.clearedExecutorTimeoutFillPromise')
        }
        if(adopted > 0) incrementQueueWakeupMetric('pump.changed.adoptedExecutorTimeoutQueuedRuntimeAction', adopted)
        if(preserved > 0) incrementQueueWakeupMetric('pump.changed.preservedExecutorTimeoutQueuedRuntimeAction', preserved)
        if(pruned > 0) incrementQueueWakeupMetric('pump.changed.prunedExecutorTimeoutQueuedRuntimeAction', pruned)
        recordCoordinatorDiagnosticEvent(
            'coordinator-executor-timeout-queued-runtime-recovered',
            `${adopted} queued runtime action(s) adopted, ${preserved} preserved, and ${pruned} pruned after executor enqueue timeout`
        )
        scheduleQueuedWorkContinuation(options.reason || 'coordinator-executor-enqueue-timeout')
    }

    return {
        changed: adopted + preserved + pruned > 0,
        adopted,
        preserved,
        pruned,
        deferred,
        fillPromiseCleared,
        keys,
        reason: adopted > 0
            ? 'coordinator-executor-enqueue-timeout-runtime-adopted'
            : preserved > 0
            ? 'coordinator-executor-enqueue-timeout-runtime-preserved'
            : pruned > 0
            ? 'coordinator-executor-enqueue-timeout-runtime-pruned'
            : 'no-matching-timeout-runtime-actions'
    }
}

async function recoverQueuedRuntimeActionBeforeOpen(action = {}, options = {}) {
    const currentAuthorityState = options.currentAuthorityState || coordinatorAuthority.current() || null
    const entry = getQueuedRuntimeActionAuthorityEntry(action, currentAuthorityState)
    const item = entry.item || null
    if(`${item?.status || ''}`.trim() !== 'queued') {
        return {changed: false, adopted: false, deferred: false, reason: 'queued-runtime-action-not-durable-queued'}
    }
    if(queuedRuntimeActionHasActiveOrPendingSurface(action)) {
        return {changed: false, adopted: false, deferred: true, reason: 'queued-runtime-action-already-has-runtime-surface'}
    }

    const recovery = await getRecoverableLiveTabForQueuedRuntimeAction(action, entry, {
        currentAuthorityState,
        liveProfileTabsByHref: options.liveProfileTabsByHref || null
    })
    if(recovery.tab) {
        const ownerTabId = action?.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID
        const adopted = await adoptLiveCoordinatorQueuedTab(
            item,
            entry.key || entry.href,
            recovery.tab,
            ownerTabId,
            {currentAuthorityState}
        ).catch(() => false)
        if(adopted) {
            return {
                changed: true,
                adopted: true,
                deferred: false,
                reason: 'queued-runtime-action-live-tab-adopted-before-open',
                tabId: normalizeTabId(recovery.tab?.id)
            }
        }
    }

    if(recovery.deferred === true) {
        return {
            changed: false,
            adopted: false,
            deferred: true,
            reason: recovery.reason || 'queued-runtime-action-live-tab-needs-reconcile',
            liveProfileTabs: recovery.liveProfileTabs || 0
        }
    }

    return {changed: false, adopted: false, deferred: false, reason: recovery.reason || 'queued-runtime-action-no-live-tab'}
}

// rolledBackQueuedTabRetryClassification is constructed here, in place at
// this cluster's old source-text position (decomposition Slice 23, part
// 2): no already-extracted module eagerly references any of its exported
// names at its own construction call site in sw.js, so no early-
// construction reordering is needed (contrast with
// queuedRuntimeActionMatching, this slice's other module, constructed well
// above -- see that module's header comment). It needs
// isQueuedTabAttemptBudgetExhausted (queuedTabRuntimeStatus, above) among
// its handlers, which is exactly the dependency that ruled out folding this
// cluster into queuedRuntimeActionMatching instead.
const rolledBackQueuedTabRetryClassification = createRolledBackQueuedTabRetryClassification({
    now: () => Date.now(),
    constants: {
        QUEUE_LOAD_THROTTLE_MAX_MS,
        STALE_QUEUED_TAB_MAX_RETRIES,
        JOB_EVENT_RETRY
    },
    handlers: {
        isTerminalCoordinatorStatus,
        isActiveCoordinatorStatus,
        isCoordinatorQueueAuthoritativeItem,
        getAttemptIdFromValue,
        getAttemptNumberFromValue,
        getCoordinatorFailureRetryCount,
        getQueuedTabMaxRetries,
        normalizeTabId,
        getQueueLoadThrottle,
        normalizeQuoraProfileUrl,
        normalizeAttemptId,
        isQueuedTabAttemptBudgetExhausted,
        makeAttemptId,
        getNextAttemptNumberFromValue,
        reduceJobEvent,
        getCoordinatorActionKindForRequestedAction,
        applyCoordinatorJobEnvelope,
        makeEmptyCoordinatorMilestones,
        getCoordinatorItemHref,
        getQueuedTabRetryAttempt,
        normalizeProgressPatch,
        getCoordinatorItemExecutorTabAction,
        getCoordinatorItemOpenUrl,
        getCoordinatorItemQueueKey,
        normalizeCoordinatorRequestedUrl,
        isProfileResolutionItem,
        isQueuedTabRetryBudgetReleaseReason: isQueuedTabRetryBudgetReleaseReasonFromJobState,
        shouldAdvanceRolledBackQueuedTabBeforeOpen: shouldAdvanceRolledBackQueuedTabBeforeOpenFromJobState,
        getRolledBackQueuedTabRetryAttempt: getRolledBackQueuedTabRetryAttemptFromJobState,
        isExhaustedRolledBackQueuedTabRetry: isExhaustedRolledBackQueuedTabRetryFromJobState,
        isActiveTransitionRolledBackQueuedTabRetry: isActiveTransitionRolledBackQueuedTabRetryFromJobState,
        isRuntimeDisappearedRolledBackQueuedTabRetry: isRuntimeDisappearedRolledBackQueuedTabRetryFromJobState,
        isTransientOpenRolledBackQueuedTabRetry: isTransientOpenRolledBackQueuedTabRetryFromJobState
    }
})
const {
    getQueuedActionNoForegroundFallback,
    markQueuedTabExecutorActionPlanned,
    isQueuedTabRetryBudgetReleaseReason,
    captureQueueLoadPressureReading,
    getExhaustedRolledBackQueuedTabTerminalError,
    shouldAdvanceRolledBackQueuedTabBeforeOpen,
    getRolledBackQueuedTabRetryAttempt,
    isExhaustedRolledBackQueuedTabRetry,
    isActiveTransitionRolledBackQueuedTabRetry,
    isRuntimeDisappearedRolledBackQueuedTabRetry,
    isTransientOpenRolledBackQueuedTabRetry,
    shouldRecoverExhaustedOpenRetryUnderQueuePressure,
    shouldRecoverExhaustedRolledBackQueuedTabRetry,
    wouldActiveMissingTabRequeueExhaustRetryBudget,
    makeExhaustedRolledBackQueuedTerminalizationKey,
    buildRolledBackQueuedTabRetryAction,
    buildForcedRolledBackQueuedTabRetryItem,
    buildQueuedDirectBlockActionRetryRecord,
    buildQueuedProfileActionGateRetryRecord,
    buildCoordinatorExecutorActionForQueuedItem
} = rolledBackQueuedTabRetryClassification

const queuedTabExecutorPlan = createQueuedTabExecutorPlan({
    handlers: {
        promiseWithTimeout,
        shouldOpenQueuedTabAction,
        recordFlightRecorderEvent,
        getAttemptIdFromValue,
        getAttemptNumberFromValue,
        scheduleCoordinatorQueueResume,
        scheduleCoordinatorReconcile,
        markQueuedTabExecutorActionPlanned
    },
    constants: {
        QUEUED_TAB_ACTION_CLAIM_NUDGE_TIMEOUT_MS
    }
})
const {
    planQueuedTabExecutorAction
} = queuedTabExecutorPlan

async function reprimeRecoveredServiceWorkerQueuedAction(item = {}, itemKey = '', options = {}) {
    if(!item || `${item.status || ''}`.trim() !== 'queued') return {reprimed: 0, reason: 'not-queued'}
    if(item.serviceWorkerOwned !== true && item.executorOwner !== 'service-worker') {
        return {reprimed: 0, reason: 'not-service-worker-owned'}
    }

    const currentAuthorityState = options.currentAuthorityState || coordinatorAuthority.current() || null
    const tabAction = getCoordinatorItemExecutorTabAction(item, options.tabAction)
    const actionSubjectKey = getCoordinatorItemHref(item) ||
        getCoordinatorItemQueueKey(item, itemKey) ||
        `${itemKey || ''}`.trim()
    const actionKey = getQueuedTabActionKey(SERVICE_WORKER_QUEUE_OWNER_ID, actionSubjectKey, tabAction)
    if(actionKey && collectQueuedTabActionKeys(SERVICE_WORKER_QUEUE_OWNER_ID).has(actionKey)) {
        return {reprimed: 0, reason: 'action-already-queued'}
    }

    const executorAction = buildCoordinatorExecutorActionForQueuedItem(
        item,
        SERVICE_WORKER_QUEUE_OWNER_ID,
        null,
        {
            ...options,
            fallbackKey: actionSubjectKey,
            tabAction
        }
    )
    const plannedAction = executorAction
        ? await planQueuedTabExecutorAction(executorAction, {currentAuthorityState})
        : null
    if(!plannedAction) return {reprimed: 0, reason: 'plan-declined'}
    if(options.awaitFill === false) {
        plannedAction.planOnlyQueuedAuthority = true
    }

    queueRuntime.enqueueActivationIntent(plannedAction, {
        front: true,
        source: 'repair-reprime'
    })
    return {
        reprimed: 1,
        reason: 'reprimed-recovered-service-worker-action'
    }
}

async function reprimeFreshQueuedTabActionsForPrunedStaleAttempts(plannedActions = [], ownerTabId = null, ownerWindowId = null, options = {}) {
    if(!plannedActions.length) return {reprimed: 0, reason: 'no-planned-actions'}

    // 2026-10-03: scoped to just this call's own hrefs instead of the full
    // 32-shard progress fetch -- neither this function nor
    // refreshResidentCoordinatorAuthorityState/planQueuedTabExecutorAction
    // downstream ever reads currentAuthorityState.progress, so the full
    // fetch was pure waste (confirmed live: currentAuthority.load.unscoped
    // was 1017 calls / 3.4GB / ~406s in one 20-minute run, by far the
    // biggest single storage-read cost).
    const knownHrefs = getNormalizedProfileHrefList(
        plannedActions.map(staleAction => staleAction?.profileHref || staleAction?.url || '')
    )
    const currentAuthorityState = await coordinatorQueueReader.currentAuthority({}, {profileHrefs: knownHrefs})
        .catch(() => null)
    const queue = currentAuthorityState?.queue || null
    if(!queue) return {reprimed: 0, reason: 'authority-load-failed'}


    const existingKeys = collectQueuedTabActionKeys(ownerTabId)
    const seen = new Set()
    const freshActions = []
    for(const staleAction of plannedActions) {
        const href = normalizeQuoraProfileUrl(staleAction?.profileHref || staleAction?.url || '')
        const coordinatorKey = staleAction?.coordinatorKey ||
            (href ? href : makeProfileResolutionQueueKey(staleAction?.requestedUrl || staleAction?.url || ''))
        const entry = coordinatorKey && queue[coordinatorKey]
            ? {key: coordinatorKey, item: queue[coordinatorKey]}
            : findCoordinatorQueueEntryForHref(queue, href)
        const item = entry?.item || null
        if(!item || `${item.status || ''}`.trim() !== 'queued') continue

        const tabAction = getCoordinatorItemExecutorTabAction(item, staleAction?.tabAction || options.tabAction)
        const actionSubjectKey = getCoordinatorItemHref(item) || getCoordinatorItemQueueKey(item, entry?.key || '') || href || coordinatorKey
        const actionKey = getQueuedTabActionKey(ownerTabId, actionSubjectKey, tabAction)
        if(actionKey && (existingKeys.has(actionKey) || seen.has(actionKey))) continue

        const executorAction = buildCoordinatorExecutorActionForQueuedItem(item, ownerTabId, ownerWindowId, {
            ...options,
            fallbackKey: entry?.key || coordinatorKey,
            tabAction
        })
        const plannedAction = executorAction
            ? await planQueuedTabExecutorAction(executorAction, {currentAuthorityState})
            : null
        if(!plannedAction) continue

        freshActions.push(plannedAction)
        if(actionKey) {
            seen.add(actionKey)
            existingKeys.add(actionKey)
        }
    }

    if(freshActions.length) {
        queueRuntime.enqueueActivationIntents(freshActions, {
            front: true,
            source: 'repair-reprime'
        })
    }
    return {
        reprimed: freshActions.length,
        reason: freshActions.length ? 'reprimed-current-authority-actions' : 'no-current-authority-actions'
    }
}

// queuedActivationSubjectKeys constructs in place at this cluster's old
// source-text position (decomposition Slice 24) -- no already-extracted
// module eagerly references any of its five exports at its own
// construction call site, so there's no ordering constraint forcing it
// earlier. getCoordinatorItemHref and getEffectiveQueuedTabConcurrency are
// still plain hoisted function declarations further below in this file
// (out of scope, part of the async orchestration layer's supporting cast)
// -- hoisted declarations are visible throughout their enclosing scope
// regardless of textual position, so no thunk is needed.
const queuedActivationSubjectKeys = createQueuedActivationSubjectKeys({
    handlers: {
        normalizeQuoraProfileUrl,
        getCoordinatorItemHref,
        getCoordinatorItemQueueKey,
        queueRuntime,
        getQueuedTabMetadata,
        getEffectiveQueuedTabConcurrency
    },
    constants: {
        COORDINATOR_EXECUTOR_PLAN_BATCH_FALLBACK_LIMIT
    }
})
const {
    getQueuedActivationIntentSubjectKey,
    getPendingCoordinatorItemSubjectKey,
    filterCurrentPendingItemsForPlannedActions,
    countQueuedExecutorSlotsForOwner,
    getCoordinatorExecutorPlanBatchLimit
} = queuedActivationSubjectKeys

async function reprimeFreshQueuedTabActionsForCurrentPendingItems(pendingItems = [], ownerTabId = null, ownerWindowId = null, options = {}) {
    if(!pendingItems.length) return {reprimed: 0, reason: 'no-pending-items'}

    // 2026-10-03: see reprimeFreshQueuedTabActionsForPrunedStaleAttempts's
    // identical note -- this function's own body, refreshResidentCoordinatorAuthorityState,
    // and planQueuedTabExecutorAction never read currentAuthorityState.progress,
    // so scoping it to just this call's hrefs is correctness-neutral. This
    // was the single hottest unscoped call site measured live (61 calls in
    // one 20-minute run via the refreshedAuthority metric below).
    const knownHrefs = getNormalizedProfileHrefList(
        pendingItems.map(pendingItem => getCoordinatorItemHref(pendingItem))
    )
    const currentAuthorityState = await coordinatorQueueReader.currentAuthority({}, {profileHrefs: knownHrefs})
        .catch(() => null)
    const queue = currentAuthorityState?.queue || null
    if(!queue) return {reprimed: 0, reason: 'authority-load-failed'}


    const existingKeys = collectQueuedTabActionKeys(ownerTabId)
    const seen = new Set()
    const freshActions = []
    const keys = []
    const limit = Math.max(1, Number.parseInt(options.limit, 10) || 1)
    const liveProfileTabsByHref = options.liveProfileTabsByHref instanceof Map
        ? options.liveProfileTabsByHref
        : new Map()

    for(const pendingItem of pendingItems || []) {
        if(freshActions.length >= limit) break

        const href = getCoordinatorItemHref(pendingItem)
        const coordinatorKey = getCoordinatorItemQueueKey(pendingItem)
        const actionSubjectKey = href || coordinatorKey
        if(!actionSubjectKey) continue

        const item = href && queue[href]
            ? queue[href]
            : queue[coordinatorKey] || queue[actionSubjectKey] || null
        if(!item || `${item.status || ''}`.trim() !== 'queued') continue
        if(!shouldResumeCoordinatorItem(item, liveProfileTabsByHref, {record: null})) continue

        const tabAction = getCoordinatorItemExecutorTabAction(item, pendingItem?.tabAction || options.tabAction)
        const currentHref = getCoordinatorItemHref(item)
        const currentCoordinatorKey = getCoordinatorItemQueueKey(item, actionSubjectKey)
        const currentSubjectKey = currentHref || currentCoordinatorKey || actionSubjectKey
        const actionKey = getQueuedTabActionKey(ownerTabId, currentSubjectKey, tabAction)
        if(actionKey && (existingKeys.has(actionKey) || seen.has(actionKey))) continue

        const executorAction = buildCoordinatorExecutorActionForQueuedItem(item, ownerTabId, ownerWindowId, {
            ...options,
            fallbackKey: actionSubjectKey,
            tabAction
        })
        const plannedAction = executorAction
            ? await planQueuedTabExecutorAction(executorAction, {currentAuthorityState})
            : null
        if(!plannedAction) continue

        freshActions.push(plannedAction)
        keys.push(currentSubjectKey)
        if(actionKey) {
            seen.add(actionKey)
            existingKeys.add(actionKey)
        }
    }

    if(freshActions.length) {
        queueRuntime.enqueueActivationIntents(freshActions, {
            front: true,
            source: 'machine-intent'
        })
    }
    return {
        reprimed: freshActions.length,
        keys,
        reason: freshActions.length ? 'reprimed-current-pending-authority-actions' : 'no-current-pending-authority-actions'
    }
}

async function terminalizeExhaustedRolledBackQueuedCoordinatorItem(itemKey = '', expectedItem = null, options = {}) {
    if(!itemKey || !isExhaustedRolledBackQueuedTabRetry(expectedItem)) {
        return {changed: false, reason: 'not-exhausted-rolled-back-row'}
    }

    const terminalizationKey = makeExhaustedRolledBackQueuedTerminalizationKey(itemKey, expectedItem)
    if(terminalizeExhaustedRolledBackQueuedPromises.has(terminalizationKey)) {
        incrementQueueWakeupMetric('reconcile.exhaustedRolledBackQueued.item.coalesced')
        return terminalizeExhaustedRolledBackQueuedPromises.get(terminalizationKey)
    }

    const expectedAttemptId = getAttemptIdFromValue(expectedItem)
    const expectedAttemptNumber = getAttemptNumberFromValue(expectedItem)
    const now = Date.now()
    const reason = options.reason || 'active-transition-retry-budget-exhausted'
    const terminalizeCurrentItem = currentItem => buildTerminalCoordinatorQueueItem(currentItem, {
        status: 'failed',
        outcome: 'timeout',
        error: getExhaustedRolledBackQueuedTabTerminalError(currentItem),
        reason,
        eventType: JOB_EVENT_TAB_REMOVED,
        now
    })

    const authorityOperation = {
        operationKind: 'terminalize-exhausted-rolled-back-queued',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'reconcile.exhaustedRolledBackQueued.save',
        currentAuthorityState: null,
        mutate(currentItem, context) {
            if(isTerminalCoordinatorStatus(currentItem?.status)) {
                return context.reject('already-terminal-row')
            }
            if(!isExhaustedRolledBackQueuedTabRetry(currentItem)) {
                return context.reject('not-exhausted-rolled-back-row')
            }
            return terminalizeCurrentItem(currentItem)
        }
    }
    const terminalizationPromise = (async () => {
        const authorityResult = getActiveStorageContext()
            ? await coordinatorAuthority.applyWithinStorageUpdate(authorityOperation)
            : await coordinatorAuthority.apply(authorityOperation)

        if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
            return {
                changed: false,
                reason: authorityResult?.reason || 'authority-apply-failed'
            }
        }

        recordFlightRecorderEvent({
            kind: 'retry-budget-terminalization',
            source: 'terminalizeExhaustedRolledBackQueuedCoordinatorItem',
            rowKey: itemKey,
            targetUrl: getCoordinatorItemHref(expectedItem) || expectedItem.requestedUrl || itemKey,
            attemptId: expectedAttemptId,
            attemptNumber: expectedAttemptNumber,
            runId: expectedItem.runId || '',
            statusBefore: expectedItem.status || '',
            statusAfter: 'failed',
            reason,
            accepted: true,
            durable: true
        })

        const currentAuthorityState = coordinatorAuthority.current()
        const nextQueue = currentAuthorityState.queue
        const runId = authorityResult.nextRow?.runId || expectedItem.runId || ''
        const affectedRunIds = runId ? new Set([runId]) : new Set()

        if(affectedRunIds.size) {
            try {
                await applyCoordinatorRunsUpdate(nextQueue, affectedRunIds, {
                    metricPath: 'reconcile.exhaustedRolledBackQueued.derivedRuns',
                    queueOperation: 'terminalize-exhausted-rolled-back-queued-derived',
                    queueChangedRows: 0
                })
            }
            catch(error) {
                recordCoordinatorDiagnosticEvent(
                    'terminalize-exhausted-rolled-back-queued-derived-save-failed',
                    error?.message || 'Exhausted rolled-back queue row derived save failed'
                )
                scheduleCoordinatorReconcile(1000, {
                    reason: 'terminalize-exhausted-rolled-back-queued-derived-save-failed',
                    edgeTriggered: true
                })
            }
        }

        return {
            changed: true,
            reason: 'terminalized-exhausted-rolled-back-row'
        }
    })()
        .finally(() => {
            terminalizeExhaustedRolledBackQueuedPromises.delete(terminalizationKey)
        })
    terminalizeExhaustedRolledBackQueuedPromises.set(terminalizationKey, terminalizationPromise)
    return terminalizationPromise
}

async function recoverExhaustedRolledBackQueuedCoordinatorItem(itemKey = '', expectedItem = null, options = {}) {
    if(!itemKey || !isExhaustedRolledBackQueuedTabRetry(expectedItem)) {
        return {changed: false, reason: 'not-exhausted-rolled-back-row'}
    }

    const expectedAttemptId = getAttemptIdFromValue(expectedItem)
    const expectedAttemptNumber = getAttemptNumberFromValue(expectedItem)
    const now = Number.parseInt(options.now, 10) || Date.now()
    const recoverReason = options.reason || 'executor-plan-active-transition-retry-budget-recovered'
    const authorityOperation = {
        operationKind: 'recover-exhausted-rolled-back-queued',
        rowKey: itemKey,
        expectedAttemptId,
        expectedAttemptNumber,
        reason: 'ordinaryMutation',
        metricPath: 'reconcile.exhaustedRolledBackQueued.recover.save',
        projectionPayload: 'queueViewOnly',
        suppressDurableIdleResume: options.suppressRecoveredQueueResume === true,
        // The caller's snapshot can predate a terminal write to the same row (the batch reconcile
        // collects its items before awaiting), and a snapshot-driven apply would re-seed the archived
        // row as queued. Read the resident authority instead, so an already-archived row rejects.
        forceFreshAuthorityState: true,
        mutate(currentItem, context) {
            if(!isExhaustedRolledBackQueuedTabRetry(currentItem)) {
                return context.reject('not-exhausted-rolled-back-row')
            }
            const nextItem = buildForcedRolledBackQueuedTabRetryItem(currentItem, now, recoverReason, options)
            if(!nextItem) return context.reject('recovery-reducer-rejected')
            return nextItem
        }
    }
    const authorityResult = getActiveStorageContext()
        ? await coordinatorAuthority.applyWithinStorageUpdate(authorityOperation)
        : await coordinatorAuthority.apply(authorityOperation)

    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {
            changed: false,
            reason: authorityResult?.reason || 'authority-apply-failed'
        }
    }

    recordFlightRecorderEvent({
        kind: 'retry-budget-recovery',
        source: 'recoverExhaustedRolledBackQueuedCoordinatorItem',
        rowKey: itemKey,
        targetUrl: getCoordinatorItemHref(expectedItem) || expectedItem.requestedUrl || itemKey,
        attemptId: expectedAttemptId,
        attemptNumber: expectedAttemptNumber,
        runId: expectedItem.runId || '',
        statusBefore: expectedItem.status || '',
        statusAfter: authorityResult.nextRow?.status || 'queued',
        reason: recoverReason,
        accepted: true,
        durable: true
    })
    if(options.suppressRecoveredQueueResume !== true) {
        scheduleCoordinatorQueueResume(1000, 'exhausted-rolled-back-queued-recovered', {
            allowBeforeQuora: true
        })
    }
    if(options.suppressRecoveredWorkContinuation !== true) {
        scheduleQueuedWorkContinuation('exhausted-rolled-back-queued-recovered')
    }
    const currentReprimeAuthorityState = coordinatorAuthority.current()
    const recoveredRow = authorityResult.nextRow || currentReprimeAuthorityState?.queue?.[itemKey] || null
    const reprimeAuthorityState = currentReprimeAuthorityState?.queue && recoveredRow
        ? {
            ...currentReprimeAuthorityState,
            queue: {
                ...currentReprimeAuthorityState.queue,
                [itemKey]: recoveredRow
            }
        }
        : currentReprimeAuthorityState
    const reprimeResult = options.suppressRecoveredActionReprime === true
        ? {reprimed: 0, reason: 'reprime-suppressed-by-caller'}
        : await reprimeRecoveredServiceWorkerQueuedAction(
            recoveredRow,
            itemKey,
            {
                currentAuthorityState: reprimeAuthorityState
            }
        ).catch(error => ({
            reprimed: 0,
            reason: 'reprime-recovered-service-worker-action-error',
            error: error?.message || `${error || ''}`
        }))
    if(reprimeResult?.reprimed > 0) {
        incrementQueueWakeupMetric('pump.changed.reprimedRecoveredExhaustedRolledBack', reprimeResult.reprimed)
    }
    return {
        changed: true,
        recovered: true,
        status: authorityResult.nextRow?.status || 'queued',
        item: authorityResult.nextRow || null,
        itemKey,
        reprimed: reprimeResult?.reprimed || 0,
        reason: 'recovered-exhausted-rolled-back-row'
    }
}

async function materializeQueuedCoordinatorItemAttemptIdentity(itemKey = '', expectedItem = null, options = {}) {
    if(!itemKey || !expectedItem || `${expectedItem.status || ''}`.trim() !== 'queued') {
        return {changed: false, reason: 'not-queued-row'}
    }
    if(getAttemptIdFromValue(expectedItem) && getAttemptNumberFromValue(expectedItem)) {
        return {changed: false, reason: 'attempt-identity-present'}
    }
    if(expectedItem.serviceWorkerOwned !== true && expectedItem.executorOwner !== 'service-worker') {
        return {changed: false, reason: 'not-service-worker-owned'}
    }

    const now = Number.parseInt(options.now, 10) || Date.now()
    const materializedAttemptId = makeAttemptId()
    const materializedAttemptNumber = getNextAttemptNumberFromValue(expectedItem)
    const maxRetries = Math.max(
        Number.parseInt(expectedItem?.maxRetries, 10) || STALE_QUEUED_TAB_MAX_RETRIES,
        materializedAttemptNumber
    )
    const maxAttempts = Math.max(
        Number.parseInt(expectedItem?.maxAttempts, 10) || 0,
        Number.parseInt(expectedItem?.attempt?.max, 10) || 0,
        materializedAttemptNumber + 1,
        maxRetries + 1
    )
    const actionKind = getCoordinatorActionKindForRequestedAction(
        expectedItem.actionKind || expectedItem.tabAction || expectedItem.executorTabAction || ''
    )
    const buildMaterializedItem = currentItem => applyCoordinatorJobEnvelope({
        ...currentItem,
        actionKind,
        attempt: {
            id: materializedAttemptId,
            number: materializedAttemptNumber,
            max: maxAttempts
        },
        attemptId: materializedAttemptId,
        attemptNumber: materializedAttemptNumber,
        maxAttempts,
        retryAttempt: Number.parseInt(currentItem?.retryAttempt, 10) || 0,
        maxRetries,
        status: 'queued',
        outcome: '',
        error: '',
        updatedAt: now,
        queuedAt: Number.parseInt(currentItem?.queuedAt, 10) || now,
        activeAt: 0,
        terminalAt: 0,
        tabId: null,
        actionLease: null,
        actionLeaseReleasedAt: now,
        actionLeaseReleaseReason: 'queued-attempt-identity-materialized'
    }, {
        runInput: {id: currentItem.runId || '', sourceType: currentItem.source?.type || currentItem.scope?.type || ''},
        source: currentItem.source || {},
        runId: currentItem.runId || '',
        targetProfileHref: getCoordinatorItemHref(currentItem),
        requestedUrl: currentItem.requestedUrl || getCoordinatorItemHref(currentItem),
        coordinatorKey: currentItem.coordinatorKey || getCoordinatorItemHref(currentItem),
        actionKind
    })

    const authorityOperation = {
        operationKind: 'materialize-queued-attempt-identity',
        rowKey: itemKey,
        expectedAttemptId: '',
        expectedAttemptNumber: 0,
        reason: 'ordinaryMutation',
        metricPath: 'coordinatorExecutor.materializeQueuedAttemptIdentity.save',
        projectionPayload: 'queueViewOnly',
        currentAuthorityState: options.currentAuthorityState || null,
        mutate(currentItem, context) {
            if(!currentItem || `${currentItem.status || ''}`.trim() !== 'queued') {
                return context.reject('not-queued-row')
            }
            if(getAttemptIdFromValue(currentItem) && getAttemptNumberFromValue(currentItem)) {
                return context.reject('attempt-identity-present')
            }
            if(currentItem.serviceWorkerOwned !== true && currentItem.executorOwner !== 'service-worker') {
                return context.reject('not-service-worker-owned')
            }
            return buildMaterializedItem(currentItem)
        }
    }
    const authorityResult = getActiveStorageContext()
        ? await coordinatorAuthority.applyWithinStorageUpdate(authorityOperation)
        : await coordinatorAuthority.apply(authorityOperation)

    if(authorityResult?.accepted !== true || authorityResult?.durable !== true) {
        return {
            changed: false,
            reason: authorityResult?.reason || 'authority-apply-failed'
        }
    }

    recordFlightRecorderEvent({
        kind: 'queued-attempt-identity-materialization',
        source: 'materializeQueuedCoordinatorItemAttemptIdentity',
        rowKey: itemKey,
        targetUrl: getCoordinatorItemHref(authorityResult.nextRow || expectedItem) || expectedItem.requestedUrl || itemKey,
        attemptId: materializedAttemptId,
        attemptNumber: materializedAttemptNumber,
        runId: expectedItem.runId || '',
        statusBefore: expectedItem.status || '',
        statusAfter: authorityResult.nextRow?.status || 'queued',
        reason: 'missing-attempt-identity-materialized',
        accepted: true,
        durable: true,
        changed: authorityResult.changed === true
    })

    return {
        changed: authorityResult.changed === true,
        item: authorityResult.nextRow || null,
        itemKey,
        reason: 'queued-attempt-identity-materialized'
    }
}

async function recoverExhaustedRolledBackQueuedCoordinatorItems(items = [], options = {}) {
    const limit = Math.max(0, Number.parseInt(options.limit, 10) ||
        COORDINATOR_EXHAUSTED_ROLLBACK_TERMINATE_BATCH_LIMIT)
    const recoveredKeys = []
    const errors = []
    for(const item of items || []) {
        if(recoveredKeys.length >= limit) break
        if(!isExhaustedRolledBackQueuedTabRetry(item)) continue
        const itemKey = getCoordinatorItemHref(item) || getCoordinatorItemQueueKey(item)
        if(!itemKey || recoveredKeys.includes(itemKey)) continue
        const result = await recoverExhaustedRolledBackQueuedCoordinatorItem(itemKey, item, options)
            .catch(error => ({
                changed: false,
                reason: 'recover-exhausted-rolled-back-error',
                error: error?.message || `${error || ''}`
            }))
        if(result?.changed === true) {
            recoveredKeys.push(itemKey)
        }
        else if(result?.error || result?.reason) {
            errors.push({
                itemKey,
                reason: result?.reason || 'recover-exhausted-rolled-back-failed',
                ...(result?.error ? {error: result.error} : {})
            })
        }
    }
    return {
        changed: recoveredKeys.length > 0,
        recovered: recoveredKeys.length,
        keys: recoveredKeys,
        errors,
        reason: recoveredKeys.length
            ? 'recovered-exhausted-rolled-back-rows'
            : errors[0]?.reason || 'no-exhausted-rolled-back-rows'
    }
}

async function settleExhaustedRolledBackQueuedCoordinatorItemsForExecutor(items = [], options = {}) {
    // Capture the queue-load-pressure reading ONCE for this whole batch
    // (rather than letting each item's classification, and later the
    // recovery mutation for each recovered item, each read live throttle
    // state independently): every item in this batch, and the eventual
    // buildForcedRolledBackQueuedTabRetryItem call for each recovered one,
    // shares this same options object (or a shallow copy of it), so they
    // all see the identical snapshot instead of risking a different answer
    // moments apart (the TOCTOU risk noted on buildForcedRolledBackQueuedTabRetryItem).
    const scopedOptions = options.recoverQueueLoadPressure === true && !options.queueLoadPressureSnapshot
        ? {...options, queueLoadPressureSnapshot: captureQueueLoadPressureReading()}
        : options
    const recoverable = []
    const terminalizable = []
    const seenRecoverable = new Set()
    const seenTerminalizable = new Set()
    for(const item of items || []) {
        if(!isExhaustedRolledBackQueuedTabRetry(item)) continue
        const itemKey = getCoordinatorItemHref(item) || getCoordinatorItemQueueKey(item)
        if(!itemKey) continue
        if(shouldRecoverExhaustedRolledBackQueuedTabRetry(item, scopedOptions)) {
            if(seenRecoverable.has(itemKey)) continue
            seenRecoverable.add(itemKey)
            recoverable.push(item)
            continue
        }
        if(seenTerminalizable.has(itemKey)) continue
        seenTerminalizable.add(itemKey)
        terminalizable.push(item)
    }

    const limit = Math.max(0, Number.parseInt(options.limit, 10) ||
        COORDINATOR_EXHAUSTED_ROLLBACK_TERMINATE_BATCH_LIMIT)
    const recoverLimit = Math.max(0, limit)
    const terminalizeLimit = Math.max(0, limit - Math.min(recoverable.length, recoverLimit))
    const recoveredResult = recoverable.length
        ? await recoverExhaustedRolledBackQueuedCoordinatorItems(recoverable, {
            ...scopedOptions,
            limit: recoverLimit,
            reason: options.recoverReason || options.reason || 'executor-plan-active-transition-retry-budget-recovered'
        })
        : {changed: false, recovered: 0, keys: [], errors: [], reason: 'no-recoverable-exhausted-rolled-back-rows'}
    const terminalizedResult = terminalizable.length && terminalizeLimit > 0
        ? await terminalizeExhaustedRolledBackQueuedCoordinatorItems(terminalizable, {
            ...options,
            limit: terminalizeLimit,
            reason: options.terminalizeReason || 'executor-plan-active-transition-retry-budget-exhausted'
        })
        : {changed: false, terminalized: 0, keys: [], errors: [], reason: 'no-terminalizable-exhausted-rolled-back-rows'}

    return {
        changed: recoveredResult.changed === true || terminalizedResult.changed === true,
        recovered: Number.parseInt(recoveredResult.recovered, 10) || 0,
        terminalized: Number.parseInt(terminalizedResult.terminalized, 10) || 0,
        recoveredKeys: recoveredResult.keys || [],
        terminalizedKeys: terminalizedResult.keys || [],
        keys: [
            ...(recoveredResult.keys || []),
            ...(terminalizedResult.keys || [])
        ],
        errors: [
            ...(recoveredResult.errors || []),
            ...(terminalizedResult.errors || [])
        ],
        reason: recoveredResult.changed === true
            ? recoveredResult.reason || 'recovered-exhausted-rolled-back-rows'
            : terminalizedResult.reason || recoveredResult.reason || 'no-exhausted-rolled-back-rows'
    }
}

async function terminalizeExhaustedRolledBackQueuedCoordinatorItems(items = [], options = {}) {
    if(terminalizeExhaustedRolledBackQueuedBatchPromise) {
        incrementQueueWakeupMetric('reconcile.exhaustedRolledBackQueued.batch.coalesced')
        return terminalizeExhaustedRolledBackQueuedBatchPromise
    }

    const candidates = []
    const coalescedPromises = []
    const seen = new Set()
    const liveProfileTabsByHref = options.liveProfileTabsByHref || null
    const limit = Math.max(0, Number.parseInt(options.limit, 10) ||
        COORDINATOR_EXHAUSTED_ROLLBACK_TERMINATE_BATCH_LIMIT)
    for(const item of items || []) {
        if(candidates.length >= limit) break
        if(!isExhaustedRolledBackQueuedTabRetry(item)) continue

        const itemKey = getCoordinatorItemHref(item) || getCoordinatorItemQueueKey(item)
        if(!itemKey || seen.has(itemKey)) continue
        if(liveProfileTabsByHref &&
            getLiveProfileTabForRolledBackQueuedCoordinatorReclaim(
                item,
                null,
                itemKey,
                liveProfileTabsByHref
            )) {
            continue
        }

        seen.add(itemKey)
        const terminalizationKey = makeExhaustedRolledBackQueuedTerminalizationKey(itemKey, item)
        const inFlight = terminalizeExhaustedRolledBackQueuedPromises.get(terminalizationKey)
        if(inFlight) {
            incrementQueueWakeupMetric('reconcile.exhaustedRolledBackQueued.item.coalesced')
            coalescedPromises.push(inFlight)
            continue
        }
        candidates.push({
            itemKey,
            terminalizationKey,
            expectedAttemptId: getAttemptIdFromValue(item),
            expectedAttemptNumber: getAttemptNumberFromValue(item)
        })
    }
    if(!candidates.length) {
        if(coalescedPromises.length) {
            incrementQueueWakeupMetric('reconcile.exhaustedRolledBackQueued.batch.coalescedRows')
            return Promise.all(coalescedPromises).then(results => ({
                changed: results.some(result => result?.changed === true),
                terminalized: results.filter(result => result?.changed === true).length,
                keys: [],
                reason: 'coalesced-exhausted-rolled-back-rows'
            }))
        }
        return {
            changed: false,
            terminalized: 0,
            keys: [],
            reason: 'no-exhausted-rolled-back-rows'
        }
    }

    terminalizeExhaustedRolledBackQueuedBatchPromise = enqueueSpaceFeedStorageUpdate(async () => {
        const state = await coordinatorQueueReader.runs({
            metricPath: 'reconcile.exhaustedRolledBackQueued.batch.load'
        })
        const currentAuthorityState = normalizeCoordinatorAuthorityStateInput(state)
        const originalQueue = currentAuthorityState.queue
        const nextQueue = {
            ...originalQueue
        }
        const now = Date.now()
        const reason = options.reason || 'active-transition-retry-budget-exhausted'
        const results = []
        const terminalizedKeys = []

        for(const candidate of candidates) {
            const currentItem = nextQueue[candidate.itemKey] || null
            if(isTerminalCoordinatorStatus(currentItem?.status)) continue
            if(!isExhaustedRolledBackQueuedTabRetry(currentItem)) continue
            if(candidate.expectedAttemptId && getAttemptIdFromValue(currentItem) !== candidate.expectedAttemptId) continue
            if(candidate.expectedAttemptNumber && getAttemptNumberFromValue(currentItem) !== candidate.expectedAttemptNumber) continue

            const nextRow = buildTerminalCoordinatorQueueItem(currentItem, {
                status: 'failed',
                outcome: 'timeout',
                error: getExhaustedRolledBackQueuedTabTerminalError(currentItem),
                reason,
                eventType: JOB_EVENT_TAB_REMOVED,
                now
            })
            if(JSON.stringify(nextRow) === JSON.stringify(currentItem)) continue

            nextQueue[candidate.itemKey] = nextRow
            terminalizedKeys.push(candidate.itemKey)
            recordFlightRecorderEvent({
                kind: 'retry-budget-terminalization',
                source: 'terminalizeExhaustedRolledBackQueuedCoordinatorItems',
                rowKey: candidate.itemKey,
                targetUrl: getCoordinatorItemHref(currentItem) || currentItem.requestedUrl || candidate.itemKey,
                attemptId: candidate.expectedAttemptId,
                attemptNumber: candidate.expectedAttemptNumber,
                runId: currentItem.runId || '',
                statusBefore: currentItem.status || '',
                statusAfter: 'failed',
                reason
            })
            results.push(makeCoordinatorAuthorityApplyResult({
                operationKind: 'terminalize-exhausted-rolled-back-queued',
                rowKey: candidate.itemKey,
                reason: 'ordinaryMutation'
            }, {
                accepted: true,
                changed: true,
                durable: true,
                reason: 'reconcile',
                previousRow: currentItem,
                nextRow,
                terminal: true
            }))
        }

        if(!results.length) {
            return {
                changed: false,
                terminalized: 0,
                keys: [],
                reason: 'no-current-exhausted-rolled-back-rows'
            }
        }

        const persistence = await coordinatorAuthority.persistCoordinator(
            {results},
            {
                operationKind: 'terminalize-exhausted-rolled-back-queued',
                reason: 'ordinaryMutation',
                metricPath: 'reconcile.exhaustedRolledBackQueued.batch.queueWal',
                projectionMetricPath: 'reconcile.exhaustedRolledBackQueued.batch.projection',
                projectionPayload: 'queueViewOnly'
            }
        )
        if(persistence?.saved !== true) {
            return {
                changed: false,
                terminalized: 0,
                keys: [],
                reason: persistence?.reason || 'batch-persistence-failed'
            }
        }

        scheduleCoordinatorReconcile(1000, {
            reason: 'terminalize-exhausted-rolled-back-queued-derived-reconcile',
            edgeTriggered: true
        })
        return {
            changed: true,
            terminalized: terminalizedKeys.length,
            keys: terminalizedKeys,
            reason: 'terminalized-exhausted-rolled-back-rows'
        }
    }, {
        reason: 'coordinator-authority.terminalize-exhausted-rolled-back-queued-batch',
        timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
    })
        .finally(() => {
            const completedPromise = terminalizeExhaustedRolledBackQueuedBatchPromise
            terminalizeExhaustedRolledBackQueuedBatchPromise = null
            for(const candidate of candidates) {
                if(terminalizeExhaustedRolledBackQueuedPromises.get(candidate.terminalizationKey) === completedPromise) {
                    terminalizeExhaustedRolledBackQueuedPromises.delete(candidate.terminalizationKey)
                }
            }
        })
    for(const candidate of candidates) {
        terminalizeExhaustedRolledBackQueuedPromises.set(
            candidate.terminalizationKey,
            terminalizeExhaustedRolledBackQueuedBatchPromise
        )
    }
    return terminalizeExhaustedRolledBackQueuedBatchPromise
}

// executorEnqueueFailureClassification constructs in place at this
// cluster's old source-text position (decomposition Slice 25) -- no
// already-extracted module eagerly references any of its thirteen exports
// at its own construction call site, so there's no ordering constraint
// forcing it earlier. getEffectiveQueuedTabConcurrency is still a plain
// hoisted function declaration further below in this file -- hoisted
// declarations are visible throughout their enclosing scope regardless of
// textual position, so no thunk is needed, but it's still threaded through
// as a handler dep rather than called as a bare global.
//
// shouldRecoverQueuedAuthorityEnqueueFailureUnderPressure joined this
// module in decomposition Slice 43 (mop-up of remaining isolated singles).
// isQueuedAuthorityNoSurfaceRetryBudgetExhausted (swQueuedTabRuntimeStatus.js),
// isCoordinatorQueueAuthoritativeItem (swCoordinatorStatusRules.js), and
// getQueueLoadThrottle (swQueueWakeupMetricsShape.js) are all already bare
// consts by this point, so no thunk is needed for any of them; `now` is
// threaded through per the clock note (this function reads Date.now()).
const executorEnqueueFailureClassification = createExecutorEnqueueFailureClassification({
    now: () => Date.now(),
    constants: {
        QUEUE_LOAD_THROTTLE_MAX_MS
    },
    handlers: {
        queueRuntime,
        getDurablyActiveQueuedTabCount,
        getCapacityConsumingQueuedTabCount,
        getSchedulerBlockingQueuedExecutorCount,
        getQueuedProfileOpenReservationCount,
        getEffectiveQueuedTabOpenConcurrency,
        normalizeTabId,
        isQueuedAuthorityNoSurfaceRetryBudgetExhausted,
        isCoordinatorQueueAuthoritativeItem,
        getQueueLoadThrottle
    }
})
const {
    buildEnqueueFailureTerminalizationDiagnostics,
    getCoordinatorFailureClassification,
    buildCoordinatorFailureClassification,
    isExecutorMaterializationDeferredByCapacity,
    isQueuedExecutorCapacityConsumed,
    isExecutorEnqueueTimeoutStillMaterializing,
    coordinatorItemHasExecutorOpenAttempt,
    normalizeQueuedAuthorityEnqueueMaterializationReason,
    shouldTreatCapacityDeferralAsNoOpenForRow,
    normalizeQueuedAuthorityEnqueueMaterializationReasonForRow,
    getQueuedAuthorityEnqueueMaterializationReason,
    hasBlockingRuntimeSurfaceAfterEnqueueFailure,
    shouldRecoverLiveSurfaceAfterFinalOpenDecline,
    shouldRecoverQueuedAuthorityEnqueueFailureUnderPressure
} = executorEnqueueFailureClassification

async function recoverQueuedAuthorityLiveTabAfterMaterializationFailure(item = null, itemKey = '', record = null, options = {}) {
    if(!item || `${item.status || ''}`.trim() !== 'queued') {
        return {changed: false, unresolved: false, reason: 'queued-live-tab-recovery-not-queued'}
    }
    if(!isCoordinatorQueueAuthoritativeItem(item)) {
        return {changed: false, unresolved: false, reason: 'queued-live-tab-recovery-not-authoritative'}
    }

    const liveProfileTabsByHref = await getLiveProfileTabsByHref().catch(() => new Map())
    const safeTab = getLiveTabForCoordinatorItem(item, itemKey, liveProfileTabsByHref, record) ||
        getLiveProfileTabForRolledBackQueuedCoordinatorReclaim(item, record, itemKey, liveProfileTabsByHref) ||
        await getWorkerSurfaceLiveTabForQueuedCoordinatorItem(item, itemKey, liveProfileTabsByHref, record)
    if(safeTab) {
        const tabId = normalizeTabId(safeTab?.id)
        const adopted = await adoptLiveCoordinatorQueuedTab(
            item,
            itemKey,
            safeTab,
            options.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
            {currentAuthorityState: options.currentAuthorityState || null}
        ).catch(() => false)
        if(adopted) {
            const currentAuthorityState = coordinatorAuthority.current() || options.currentAuthorityState || null
            await pruneQueuedTabActions(options.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID, {
                queueOnlyAuthority: options.queueOnlyAuthority === true,
                currentAuthorityState,
                ignoreActiveFillPromise: true,
                reason: 'queued-live-tab-adopted-after-materialization-timeout'
            }).catch(() => null)
            return {
                changed: true,
                adopted: true,
                unresolved: false,
                reason: 'queued-live-tab-adopted-after-materialization-timeout',
                tabId,
                currentAuthorityState,
                liveProfileTabsByHref
            }
        }
        const tabStatus = await getQueuedExecutorTabStatusWithTimeout(tabId, 'queued-live-tab-adoption-after-materialization-failed')
        if(tabStatus.missing) {
            detachQueuedTabRuntimeState(tabId, 'queued-live-tab-adoption-vanished')
            await releaseCoordinatorActionLeaseForTab(tabId, 'queued-live-tab-adoption-vanished').catch(() => null)
            scheduleCoordinatorQueueResume(1000, 'queued-live-tab-adoption-vanished', {
                allowBeforeQuora: true
            })
            scheduleCoordinatorReconcile(1000, {
                reason: 'queued-live-tab-adoption-vanished',
                edgeTriggered: true,
                allowBeforeQuora: true
            })
            return {
                changed: false,
                unresolved: false,
                reason: 'queued-live-tab-recovery-vanished-before-adoption',
                tabId,
                liveProfileTabsByHref
            }
        }
        return {
            changed: false,
            unresolved: true,
            reason: 'queued-live-tab-adoption-after-materialization-timeout-failed',
            tabId,
            liveProfileTabsByHref
        }
    }

    const href = getCoordinatorItemHref(item) || normalizeQuoraProfileUrl(itemKey) || normalizeQuoraProfileUrl(record?.profileHref || '')
    if(!href) {
        return {
            changed: false,
            unresolved: false,
            reason: 'queued-live-tab-recovery-no-live-profile-tab',
            liveProfileTabsByHref
        }
    }

    const liveTabs = getLiveTabsForProfileHref(liveProfileTabsByHref, href)
        .filter(tab => normalizeTabId(tab?.id))
    if(liveTabs.length) {
        const runtimeSurface = options.runtimeSurface && typeof options.runtimeSurface === 'object'
            ? options.runtimeSurface
            : null
        const hasActiveOrPendingRuntimeSurface = (runtimeSurface?.activeTabs || []).length > 0 ||
            (runtimeSurface?.pendingActions || []).length > 0
        if(hasActiveOrPendingRuntimeSurface) {
            return {
                changed: false,
                unresolved: false,
                reason: 'queued-live-tab-recovery-deferred-to-runtime-surface',
                liveProfileTabsByHref
            }
        }
        if(liveTabs.length > 1) {
            const selectedTab = chooseCoordinatorReclaimProfileTab(liveTabs)
            const selectedTabId = normalizeTabId(selectedTab?.id)
            if(selectedTabId) {
                for(const extraTab of liveTabs) {
                    const extraTabId = normalizeTabId(extraTab?.id)
                    if(!extraTabId || extraTabId === selectedTabId) continue
                    markQueuedTabClosing(extraTabId, 'queued-live-tab-duplicate-reclaim')
                    cleanupQueuedTabMetadataOnly(extraTabId)
                    await browser.tabs.remove(extraTabId).catch(() => null)
                }

                const adopted = await adoptLiveCoordinatorQueuedTab(
                    item,
                    itemKey,
                    selectedTab,
                    options.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
                    {currentAuthorityState: options.currentAuthorityState || null}
                ).catch(() => false)
                if(adopted) {
                    const currentAuthorityState = coordinatorAuthority.current() || options.currentAuthorityState || null
                    await pruneQueuedTabActions(options.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID, {
                        queueOnlyAuthority: options.queueOnlyAuthority === true,
                        currentAuthorityState,
                        ignoreActiveFillPromise: true,
                        reason: 'queued-live-tab-duplicate-adopted-after-materialization-timeout'
                    }).catch(() => null)
                    incrementQueueWakeupMetric('pump.changed.adoptedDuplicateLiveTabAfterMaterialization')
                    return {
                        changed: true,
                        adopted: true,
                        unresolved: false,
                        reason: 'queued-live-tab-duplicate-adopted-after-materialization-timeout',
                        tabId: selectedTabId,
                        currentAuthorityState,
                        liveProfileTabsByHref
                    }
                }
            }
        }
        return {
            changed: false,
            unresolved: false,
            reason: 'queued-authority-live-profile-tab-unclassified',
            liveProfileTabs: liveTabs.length,
            liveProfileTabsByHref
        }
    }

    return {
        changed: false,
        unresolved: false,
        reason: 'queued-live-tab-recovery-no-live-profile-tab',
        liveProfileTabsByHref
    }
}

async function recoverQueuedActionLiveTabAfterFinalOpenDecline(action = {}, decision = {}, options = {}) {
    if(!shouldRecoverLiveSurfaceAfterFinalOpenDecline(decision)) {
        return {changed: false, unresolved: false, reason: 'final-open-decline-not-recoverable'}
    }

    const href = normalizeQuoraProfileUrl(
        action?.profileHref ||
        action?.targetProfileHref ||
        action?.targetUrl ||
        action?.requestedUrl ||
        action?.url ||
        ''
    )
    const coordinatorKey = action?.coordinatorKey ||
        (href ? href : makeProfileResolutionQueueKey(action?.requestedUrl || action?.url || ''))
    if(!href && !coordinatorKey) {
        return {changed: false, unresolved: false, reason: 'final-open-live-recovery-missing-key'}
    }

    let currentAuthorityState = getHydratedCoordinatorAuthorityState('pump.finalOpenDeclineRecovery.usedResidentAuthority')
    if(!currentAuthorityState) {
        // 2026-10-03: this only ever reads progress for `href` below (via
        // getCoordinatorProgressRecordForItem) -- scope the fetch to it.
        // When href is empty (coordinatorKey-only resolution-queue case),
        // fall back to the full fetch unchanged rather than guess.
        currentAuthorityState = await promiseWithTimeout(
            coordinatorQueueReader.currentAuthority({}, href ? {profileHrefs: [href]} : {}),
            QUEUED_TAB_DURABLE_CLAIM_TIMEOUT_MS,
            'queued tab final open recovery authority reload'
        ).catch(() => null)
    }
    const queue = currentAuthorityState?.queue || {}
    const item = (href && queue[href]) ||
        (coordinatorKey && queue[coordinatorKey]) ||
        null
    if(!item || `${item.status || ''}`.trim() !== 'queued') {
        return {changed: false, unresolved: false, reason: 'final-open-live-recovery-no-queued-item'}
    }

    const progress = currentAuthorityState?.progress || {}
    const record = getCoordinatorProgressRecordForItem(
        href || coordinatorKey,
        item,
        progress
    )
    const recovery = await applyCoordinatorQueueMachineEvent({
        type: 'QUEUED_MATERIALIZATION_FAILURE',
        item,
        itemKey: href || coordinatorKey,
        record,
        ownerTabId: action?.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
        queueOnlyAuthority: options.queueOnlyAuthority === true,
        currentAuthorityState
    })
    if(recovery?.adopted === true) {
        return {
            ...recovery,
            reason: 'queued-live-tab-adopted-after-final-open-decline'
        }
    }
    if(recovery?.unresolved === true) {
        return {
            ...recovery,
            reason: recovery.reason || 'queued-authority-live-profile-tab-unclassified'
        }
    }
    return recovery || {changed: false, unresolved: false, reason: 'final-open-live-recovery-no-live-tab'}
}

async function terminalizeQueuedAuthorityEnqueueFailureCoordinatorItems(items = [], options = {}) {
    const candidates = []
    const seen = new Set()
    const recordByKey = options.recordByKey instanceof Map
        ? options.recordByKey
        : options.recordByKey && typeof options.recordByKey === 'object'
        ? new Map(Object.entries(options.recordByKey))
        : new Map()
    for(const item of items || []) {
        if(!item || typeof item !== 'object') continue
        if(`${item.status || ''}`.trim() !== 'queued') continue
        const itemKey = getCoordinatorItemHref(item) || getCoordinatorItemQueueKey(item)
        if(!itemKey || seen.has(itemKey)) continue
        seen.add(itemKey)
        candidates.push({
            item,
            itemKey,
            record: recordByKey.get(itemKey) || recordByKey.get(getCoordinatorItemQueueKey(item, itemKey)) || null,
            expectedAttemptId: getAttemptIdFromValue(item),
            expectedAttemptNumber: getAttemptNumberFromValue(item)
        })
    }

    if(!candidates.length) {
        return {
            changed: false,
            terminalized: 0,
            keys: [],
            reason: 'no-queued-enqueue-timeout-candidates'
        }
    }

    const terminalReason = options.reason || 'queued-authority-enqueue-did-not-materialize-runtime'
    const terminalizedReason = options.terminalizedReason || `terminalized-${terminalReason}`
    const terminalOperationKind = options.operationKind || 'terminalize-queued-authority-enqueue-failure'
    const terminalMetricPath = options.metricPath || 'coordinatorExecutor.enqueueFailure.terminalize'
    const terminalSource = options.source || 'terminalizeQueuedAuthorityEnqueueFailureCoordinatorItems'
    const enqueueDiagnostics = options.enqueueDiagnostics && typeof options.enqueueDiagnostics === 'object'
        ? options.enqueueDiagnostics
        : {}
    const terminalizedKeys = []
    const requeuedKeys = []
    const skippedKeys = []
    const errors = []
    for(const candidate of candidates) {
        const latestAuthorityItem = coordinatorAuthority.current()?.queue?.[candidate.itemKey] ||
            options.currentAuthorityState?.queue?.[candidate.itemKey] ||
            null
        const latestAttemptId = getAttemptIdFromValue(latestAuthorityItem)
        const latestAttemptNumber = getAttemptNumberFromValue(latestAuthorityItem)
        if(latestAuthorityItem && (
            `${latestAuthorityItem.status || ""}`.trim() !== "queued" ||
            (candidate.expectedAttemptId && latestAttemptId !== candidate.expectedAttemptId) ||
            (candidate.expectedAttemptNumber && latestAttemptNumber !== candidate.expectedAttemptNumber))) {
            skippedKeys.push(candidate.itemKey)
            recordFlightRecorderEvent({
                kind: "enqueue-failure-terminalization-skip",
                source: terminalSource,
                rowKey: candidate.itemKey,
                targetUrl: getCoordinatorItemHref(candidate.item) || candidate.item.requestedUrl || candidate.itemKey,
                attemptId: candidate.expectedAttemptId,
                attemptNumber: candidate.expectedAttemptNumber,
                runId: candidate.item.runId || "",
                statusBefore: candidate.item.status || "",
                statusAfter: latestAuthorityItem?.status || "",
                reason: "queued-authority-enqueue-candidate-already-moved",
                accepted: true,
                durable: false
            })
            continue
        }
        const now = Date.now()
        const authorityOperation = {
            operationKind: terminalOperationKind,
            rowKey: candidate.itemKey,
            expectedAttemptId: candidate.expectedAttemptId,
            expectedAttemptNumber: candidate.expectedAttemptNumber,
            reason: 'ordinaryMutation',
            metricPath: `${terminalMetricPath}.queueWal`,
            projectionMetricPath: `${terminalMetricPath}.projection`,
            projectionPayload: 'queueViewOnly',
            currentAuthorityState: options.currentAuthorityState || null,
            mutate(currentItem, context) {
                if(isTerminalCoordinatorStatus(currentItem?.status)) {
                    return context.reject('already-terminal-row')
                }
                if(`${currentItem?.status || ''}`.trim() !== 'queued') {
                    return context.reject('row-not-queued')
                }
                if(options.retryBeforeTerminal === true &&
                    !isQueuedAuthorityNoSurfaceRetryBudgetExhausted(currentItem, candidate.record)) {
                    return buildRequeuedActiveCoordinatorItemWithoutActor(
                        currentItem,
                        candidate.record,
                        now,
                        terminalReason
                    )
                }
                if(shouldRecoverQueuedAuthorityEnqueueFailureUnderPressure(currentItem, {
                    ...options,
                    record: candidate.record
                })) {
                    return buildRequeuedActiveCoordinatorItemWithoutActor(
                        currentItem,
                        candidate.record,
                        now,
                        terminalReason,
                        {
                            forceRequeueExhaustedActorless: true,
                            extendActorlessRetryBudget: true
                        }
                    )
                }
                return buildTerminalCoordinatorQueueItem(currentItem, {
                    status: 'failed',
                    outcome: 'timeout',
                    error: options.error || 'Coordinator executor enqueue failed before materializing runtime work',
                    reason: terminalReason,
                    failureClassification: buildCoordinatorFailureClassification(
                        terminalReason,
                        options.error || 'Coordinator executor enqueue failed before materializing runtime work',
                        enqueueDiagnostics
                    ),
                    eventType: JOB_EVENT_TERMINAL,
                    now
                })
            }
        }
        const authorityResult = getActiveStorageContext()
            ? await coordinatorAuthority.applyWithinStorageUpdate(authorityOperation)
            : await coordinatorAuthority.apply(authorityOperation)

        if(authorityResult?.accepted === true && authorityResult?.durable === true) {
            const nextStatus = `${authorityResult.nextRow?.status || ''}`.trim()
            if(nextStatus === 'queued') {
                requeuedKeys.push(candidate.itemKey)
            }
            else {
                terminalizedKeys.push(candidate.itemKey)
            }
            recordFlightRecorderEvent({
                kind: nextStatus === 'queued'
                    ? 'enqueue-failure-requeue'
                    : 'enqueue-failure-terminalization',
                source: terminalSource,
                rowKey: candidate.itemKey,
                targetUrl: getCoordinatorItemHref(candidate.item) || candidate.item.requestedUrl || candidate.itemKey,
                attemptId: candidate.expectedAttemptId,
                attemptNumber: candidate.expectedAttemptNumber,
                runId: candidate.item.runId || '',
                statusBefore: candidate.item.status || '',
                statusAfter: nextStatus || 'failed',
                reason: terminalReason,
                accepted: true,
                durable: true,
                ...enqueueDiagnostics
            })
        }
        else {
            errors.push({
                itemKey: candidate.itemKey,
                reason: authorityResult?.reason || 'authority-apply-failed'
            })
        }
    }

    if(terminalizedKeys.length || requeuedKeys.length) {
        scheduleCoordinatorReconcile(1000, {
            reason: requeuedKeys.length
                ? `${terminalReason}-requeued`
                : `${terminalReason}-terminalized`,
            edgeTriggered: true,
            allowBeforeQuora: true
        })
        scheduleQueuedWorkContinuation(requeuedKeys.length
            ? `${terminalReason}-requeued`
            : `${terminalReason}-terminalized`)
    }

    return {
        changed: terminalizedKeys.length + requeuedKeys.length > 0,
        terminalized: terminalizedKeys.length,
        requeued: requeuedKeys.length,
        keys: terminalizedKeys,
        requeuedKeys,
        skippedKeys,
        errors,
        reason: requeuedKeys.length
            ? `requeued-${terminalReason}`
            : terminalizedKeys.length
            ? terminalizedReason
            : errors[0]?.reason || 'queued-authority-enqueue-timeout-terminalize-failed'
    }
}

async function validateQueuedTabOpenAgainstCurrentAuthority(action = {}) {
    let currentAuthorityState = getHydratedCoordinatorAuthorityState('pump.finalOpenDecision.usedResidentAuthority')
    const options = arguments[1] && typeof arguments[1] === 'object'
        ? arguments[1]
        : {}
    if(options.currentAuthorityState?.queue) {
        currentAuthorityState = options.currentAuthorityState
    }
    // This whole function only ever validates one row (`action`) -- scope
    // the progress-shard fetch to it instead of pulling all 32 shards. See
    // loadCoordinatorCurrentAuthorityState's own comment: this was confirmed
    // live as the dominant read cost in the coordinator's storage layer, and
    // this specific call site (plus its "fresh reload" sibling just below)
    // fires on every queued-tab final-open decision -- shouldOpenQueuedTabAction's
    // own scoped fallback never actually runs in practice because both of
    // its real callers, here, always pass a pre-loaded currentAuthorityState.
    const actionHref = normalizeQuoraProfileUrl(action?.profileHref || action?.url || '')
    if(!currentAuthorityState) {
        currentAuthorityState = await promiseWithTimeout(
            coordinatorQueueReader.actionRows('validateQueuedTabOpenAgainstCurrentAuthority.initial', action),
            QUEUED_TAB_DURABLE_CLAIM_TIMEOUT_MS,
            'queued tab final open authority reload'
        ).catch(() => null)
    }
    let openDecision = await promiseWithTimeout(
        shouldOpenQueuedTabAction(action, {
            currentAuthorityState
        }),
        QUEUED_TAB_FINAL_OPEN_DECISION_TIMEOUT_MS,
        'queued tab final open decision'
    ).catch(error => ({
        open: false,
        reason: 'queued-tab-final-open-decision-timeout',
        authorityUnavailable: true,
        error: error?.message || `${error || ''}`
    }))
    if(openDecision.open === true && options.verifyFreshAuthority !== false) {
        const freshAuthorityState = await promiseWithTimeout(
            coordinatorQueueReader.actionRows('validateQueuedTabOpenAgainstCurrentAuthority.verifyFresh', action),
            QUEUED_TAB_DURABLE_CLAIM_TIMEOUT_MS,
            'queued tab final open fresh authority reload'
        ).catch(() => null)
        if(freshAuthorityState?.queue) {
            const freshOpenDecision = await promiseWithTimeout(
                shouldOpenQueuedTabAction(action, {
                    currentAuthorityState: freshAuthorityState
                }),
                QUEUED_TAB_FINAL_OPEN_DECISION_TIMEOUT_MS,
                'queued tab final open fresh decision'
            ).catch(error => ({
                open: false,
                reason: 'queued-tab-final-open-fresh-decision-timeout',
                authorityUnavailable: true,
                error: error?.message || `${error || ''}`
            }))
            if(freshOpenDecision.open !== true) {
                return {
                    ...freshOpenDecision,
                    staleProvidedAuthority: options.currentAuthorityState?.queue ? true : false,
                    verifiedFreshAuthority: true
                }
            }
            openDecision = {
                ...freshOpenDecision,
                verifiedFreshAuthority: true
            }
        }
    }
    if(openDecision.authorityUnavailable === true) {
        scheduleCoordinatorQueueResume(QUEUED_TAB_FINAL_OPEN_AUTHORITY_RETRY_MS, 'queued-tab-final-open-authority-unavailable', {
            allowBeforeQuora: true
        })
        scheduleCoordinatorReconcile(QUEUED_TAB_FINAL_OPEN_AUTHORITY_RETRY_MS, {
            reason: 'queued-tab-final-open-authority-unavailable',
            edgeTriggered: true,
            allowBeforeQuora: true
        })
    }

    return openDecision
}

// Queued rows drain in the dashboard's display order: queueSequence ascending, then the row's
// updatedAt/createdAt time, then href (the same keys coordinator.js's compareCurrentWorkItems uses).
// Rows that are not queued keep their positions.
function orderQueuedItemsForDrain(items = []) {
    const list = Array.isArray(items) ? items.slice() : []
    const queuedIndexes = []
    const queued = []
    list.forEach((item, index) => {
        if(`${item?.status || ''}`.trim() === 'queued') {
            queuedIndexes.push(index)
            queued.push(item)
        }
    })
    queued.sort((left, right) => {
        const sequenceDiff = (Number.parseInt(left?.queueSequence, 10) || 0) - (Number.parseInt(right?.queueSequence, 10) || 0)
        if(sequenceDiff) return sequenceDiff
        const timeDiff = (Number.parseInt(left?.updatedAt || left?.createdAt || left?.at, 10) || 0) -
            (Number.parseInt(right?.updatedAt || right?.createdAt || right?.at, 10) || 0)
        if(timeDiff) return timeDiff
        return `${getCoordinatorItemHref(left) || left?.coordinatorKey || ''}`.localeCompare(
            `${getCoordinatorItemHref(right) || right?.coordinatorKey || ''}`
        )
    })
    queuedIndexes.forEach((index, position) => {
        list[index] = queued[position]
    })
    return list
}

async function enqueueExistingExecutorForCoordinatorOnce(items = [], coordinator = {}, options = {}) {
    const serviceWorkerOwned = options.serviceWorkerOwned === true ||
        coordinator?.tabId === SERVICE_WORKER_QUEUE_OWNER_ID
    const ownerTabId = serviceWorkerOwned
        ? SERVICE_WORKER_QUEUE_OWNER_ID
        : coordinator?.tabId || null
    if(!ownerTabId) return {queued: 0}
    // A reset or a timeout superseded this enqueue before it started (review-2 S2-1, S2-2): it plans nothing.
    const superseded = () => options.cancelToken?.cancelled === true
    if(superseded()) {
        recordExecutorStartSupersession(options.cancelToken, 'start')
        return supersededExecutorEnqueueResult()
    }

    await ownedTabIdsReady
    if(options.queueOnlyAuthority !== true) {
        await ensureProfileNukeProgressReady()
    }
    await pruneQueuedTabActions(ownerTabId, {
        queueOnlyAuthority: options.queueOnlyAuthority === true,
        currentAuthorityState: options.currentAuthorityState || null
    })
    await sweepStaleQueuedTabs(ownerTabId, {
        queueOnlyAuthority: options.queueOnlyAuthority === true
    })

    if(queueRuntime.resumeQueuedOwner(ownerTabId) && ownerTabId === SERVICE_WORKER_QUEUE_OWNER_ID) {
        incrementQueueWakeupMetric('pump.changed.clearedStaleServiceWorkerOwnerPause')
    }
    // 2026-09-27 removed this force-to-1, then 2026-09-29 restored it: the
    // 09-27 reasoning was that foreground actions share one worker-window
    // window but run as background tabs within it via scripting/page-world
    // injection, so running more than one at a time wasn't inherently
    // unsafe. Confirmed live 2026-09-29 that this was wrong: Chrome
    // throttles a tab's own JS timers (the content script's close-if-blocked
    // poll included) whenever its window lacks OS focus, regardless of
    // scripting-injection vs. focus-dependent execution -- a queued profile
    // tab visibly stalled for over a minute and only "came alive" once the
    // user manually raised the worker window. Two profile tabs were also
    // observed open in the worker window at once (a second forcing the
    // first out of the single "active within window" slot), compounding the
    // same throttling on both. Per explicit user request: only one tab
    // should be up in the worker window at a time, so queuedTabConcurrency
    // is forced to 1 again whenever the batch includes any foreground/
    // worker-window action -- which, per the comment this replaces, is
    // virtually every real batch ('nuke'/'mute-block'/unblock-unmute).
    const includesUnblockUnmute = (items || []).some(item =>
        getCoordinatorActionKindForRequestedAction(
            item?.actionKind || getCoordinatorItemExecutorTabAction(item, options.tabAction)
        ) === UNBLOCK_UNMUTE_ACTION_KIND
    )
    const requiresForegroundExecutor = (items || []).some(item => {
        const tabAction = getCoordinatorItemExecutorTabAction(item, options.tabAction)
        const actionKind = getCoordinatorActionKindForRequestedAction(item?.actionKind || tabAction)
        return isForegroundQueuedTabAction(actionKind || tabAction) &&
            getQueuedActionNoForegroundFallback(item, options) !== true
    })
    // Checked again after the awaits above: a superseded enqueue must not overwrite the concurrency its successor set.
    if(superseded()) {
        recordExecutorStartSupersession(options.cancelToken, 'start')
        return supersededExecutorEnqueueResult()
    }
    queuedTabConcurrency = serviceWorkerOwned && (includesUnblockUnmute || requiresForegroundExecutor)
        ? 1
        : Math.max(1, Number.parseInt(options.maxConcurrent, 10) || 1)
    const ownerWindowId = serviceWorkerOwned
        ? null
        : coordinator.windowId || options.ownerWindowId || null

    const seen = new Set()
    const queuedActionKeys = collectQueuedTabActionKeys(ownerTabId)
    const planBatchLimit = getCoordinatorExecutorPlanBatchLimit(ownerTabId, options)
    let queued = 0
    let batchLimited = false
    let terminalizedExhausted = 0
    const queuedKeys = []
    const terminalizedExhaustedKeys = []
    const plannedActions = []
    let cachedLiveProfileTabsByHref = options.liveProfileTabsByHref || null
    const getLiveProfileTabsForPlanning = async () => {
        if(!cachedLiveProfileTabsByHref) {
            cachedLiveProfileTabsByHref = await getLiveProfileTabsByHref()
        }
        return cachedLiveProfileTabsByHref
    }
    const liveProfileTabsByHrefForTerminalize = (items || []).some(isExhaustedRolledBackQueuedTabRetry)
        ? await getLiveProfileTabsForPlanning()
        : cachedLiveProfileTabsByHref
    const preTerminalizedExhausted = await applyCoordinatorQueueMachineEvent({
        type: 'EXHAUSTED_ROLLBACK_SETTLE',
        items,
        options: {
            limit: COORDINATOR_EXHAUSTED_ROLLBACK_TERMINATE_BATCH_LIMIT,
            recoverReason: 'executor-plan-active-transition-retry-budget-recovered',
            terminalizeReason: 'executor-plan-active-transition-retry-budget-exhausted',
            queueOnlyAuthority: options.queueOnlyAuthority === true,
            recoverActiveTransitionFailures: true,
            serviceWorkerOwned,
            currentAuthorityState: options.currentAuthorityState || null,
            liveProfileTabsByHref: liveProfileTabsByHrefForTerminalize
        }
    }).catch(error => ({
        changed: false,
        terminalized: 0,
        recovered: 0,
        keys: [],
        reason: 'batch-terminalize-error',
        error: error?.message || `${error || ''}`
    }))
    terminalizedExhausted += preTerminalizedExhausted?.terminalized || 0
    const recoveredExhausted = preTerminalizedExhausted?.recovered || 0
    if(recoveredExhausted > 0) {
        incrementQueueWakeupMetric('pump.changed.recoveredExhaustedRolledBack', recoveredExhausted)
    }
    if(terminalizedExhausted > 0) {
        incrementQueueWakeupMetric('pump.changed.terminalizedExhaustedRolledBack', terminalizedExhausted)
    }
    const preTerminalizedExhaustedKeys = new Set(preTerminalizedExhausted?.keys || [])
    let latestPlanAuthorityState = terminalizedExhausted > 0 || recoveredExhausted > 0
        ? coordinatorAuthority.current()
        : options.currentAuthorityState || null
    if(recoveredExhausted > 0) {
        const recoveredQueue = latestPlanAuthorityState?.queue || {}
        for(const recoveredKey of preTerminalizedExhausted?.recoveredKeys || []) {
            const recoveredItem = recoveredQueue[recoveredKey] || null
            if(!recoveredItem) continue
            await reprimeRecoveredServiceWorkerQueuedAction(recoveredItem, recoveredKey, {
                ...options,
                currentAuthorityState: latestPlanAuthorityState
            }).catch(() => ({reprimed: 0}))
        }
    }
    for(const queuedItem of orderQueuedItemsForDrain(items)) {
        if(superseded()) break
        let item = queuedItem
        let planAuthorityState = latestPlanAuthorityState
        if(queued >= planBatchLimit) {
            batchLimited = true
            break
        }
        const tabAction = getCoordinatorItemExecutorTabAction(item, options.tabAction)
        const queuedItemKey = `${queuedItem?.rowKey || queuedItem?.coordinatorKey || ''}`.trim()
        const normalizedHref = getCoordinatorItemHref(item)
        const fallbackKey = normalizedHref || getCoordinatorItemQueueKey(item, queuedItemKey) || queuedItemKey
        const url = getCoordinatorItemOpenUrl(item, fallbackKey)
        const coordinatorKey = getCoordinatorItemQueueKey(item, fallbackKey)
        const actionSubjectKey = normalizedHref || coordinatorKey
        if(actionSubjectKey && preTerminalizedExhaustedKeys.has(actionSubjectKey)) continue
        if(!url || !actionSubjectKey || seen.has(actionSubjectKey)) continue

        const latestPlanQueue = planAuthorityState?.queue || {}
        let latestItem = normalizedHref && latestPlanQueue[normalizedHref]
            ? latestPlanQueue[normalizedHref]
            : latestPlanQueue[coordinatorKey] || latestPlanQueue[actionSubjectKey] || null
        if(!latestItem) continue
        if(options.skipFreshPreflightRequeuedRows === true &&
            (/fast-executor-preflight$/.test(`${latestItem.actionLeaseReleaseReason || ''}`) ||
                `${latestItem.actionLeaseReleaseReason || ''}` === 'executor-plan-active-transition-retry-budget-recovered')) {
            continue
        }
        if(isTerminalCoordinatorStatus(latestItem.status)) {
            if(normalizedHref && !superseded()) {
                // Under the space-feed storage lock, as the other settlement callers are (review-2 S2-3).
                await enqueueSpaceFeedStorageUpdate(() => settleTerminalCoordinatorItemsLocked({profileHrefs: [normalizedHref]}), {
                    reason: 'executor-enqueue-terminal-settlement',
                    timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
                })
            }
            continue
        }
        if(!isPendingCoordinatorStatus(latestItem.status)) continue
        if(`${latestItem.status || ''}`.trim() === 'queued' &&
            (!getAttemptIdFromValue(latestItem) || !getAttemptNumberFromValue(latestItem))) {
            const materializeResult = await materializeQueuedCoordinatorItemAttemptIdentity(
                normalizedHref || coordinatorKey || actionSubjectKey,
                latestItem,
                {currentAuthorityState: planAuthorityState}
            ).catch(error => ({
                changed: false,
                reason: 'queued-attempt-identity-materialization-error',
                error: error?.message || `${error || ''}`
            }))
            if(materializeResult?.changed === true && materializeResult.item) {
                planAuthorityState = coordinatorAuthority.current()
                latestPlanAuthorityState = planAuthorityState
                latestItem = materializeResult.item
                item = latestItem
                incrementQueueWakeupMetric('pump.changed.materializedQueuedAttemptIdentity')
            }
            else if(materializeResult?.reason) {
                incrementQueueWakeupMetric(`pump.noop.materializedQueuedAttemptIdentity.${normalizeStorageMetricPathName(materializeResult.reason)}`)
            }
        }
        if(hasMismatchedCoordinatorAttempt(latestItem, item)) continue
        item = latestItem

        if(normalizedHref && isTerminalCoordinatorStatus(item?.status)) {
            if(superseded()) break
            await enqueueSpaceFeedStorageUpdate(() => settleTerminalCoordinatorItemsLocked({profileHrefs: [normalizedHref]}), {
                reason: 'executor-enqueue-terminal-settlement',
                timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
            })
            continue
        }
        if(!normalizedHref && isTerminalCoordinatorStatus(item?.status)) continue

        seen.add(actionSubjectKey)
        const actionKey = getQueuedTabActionKey(ownerTabId, actionSubjectKey, tabAction)
        if(actionKey && queuedActionKeys.has(actionKey)) continue

        let executorAction = buildCoordinatorExecutorActionForQueuedItem(item, ownerTabId, ownerWindowId, {
            ...options,
            fallbackKey: actionSubjectKey
        })
        if(!executorAction) continue
        if(shouldAdvanceRolledBackQueuedTabBeforeOpen(item)) {
            const retryAction = buildRolledBackQueuedTabRetryAction(item, executorAction)
            if(!retryAction) {
                const liveProfileTabsByHref = await getLiveProfileTabsForPlanning()
                const reclaimTab = getLiveProfileTabForRolledBackQueuedCoordinatorReclaim(
                    item,
                    null,
                    normalizedHref || coordinatorKey,
                    liveProfileTabsByHref
                )
                if(reclaimTab &&
                    await adoptLiveCoordinatorQueuedTab(item, normalizedHref || coordinatorKey, reclaimTab, ownerTabId, {
                        currentAuthorityState: planAuthorityState
                    })) {
                    latestPlanAuthorityState = coordinatorAuthority.current()
                    if(actionKey) queuedActionKeys.add(actionKey)
                    queued += 1
                    queuedKeys.push(actionSubjectKey)
                }
                else if(terminalizedExhausted < COORDINATOR_EXHAUSTED_ROLLBACK_TERMINATE_BATCH_LIMIT &&
                    isExhaustedRolledBackQueuedTabRetry(item)) {
                    const exhaustedRollbackRecoveryIntent = {
                        queueOnlyAuthority: options.queueOnlyAuthority === true,
                        recoverActiveTransitionFailures: true,
                        serviceWorkerOwned
                    }
                    const shouldRecoverRolledBack = shouldRecoverExhaustedRolledBackQueuedTabRetry(item, exhaustedRollbackRecoveryIntent)
                    const terminalizeResult = await applyCoordinatorQueueMachineEvent({
                        type: shouldRecoverRolledBack
                            ? 'EXHAUSTED_ROLLBACK_RECOVER'
                            : 'EXHAUSTED_ROLLBACK_TERMINATE',
                        itemKey: normalizedHref || coordinatorKey,
                        item,
                        options: {
                            currentAuthorityState: planAuthorityState,
                            reason: shouldRecoverRolledBack
                                ? 'executor-plan-active-transition-retry-budget-recovered'
                                : 'executor-plan-active-transition-retry-budget-exhausted',
                            ...(shouldRecoverRolledBack ? exhaustedRollbackRecoveryIntent : {})
                        }
                    }).catch(error => ({
                        changed: false,
                        reason: 'terminalize-error',
                        error: error?.message || `${error || ''}`
                    }))
                    if(terminalizeResult?.changed) {
                        if(terminalizeResult.recovered === true) {
                            incrementQueueWakeupMetric('pump.changed.recoveredExhaustedRolledBack')
                        }
                        else {
                            terminalizedExhausted += 1
                            terminalizedExhaustedKeys.push(normalizedHref || coordinatorKey || actionSubjectKey)
                            incrementQueueWakeupMetric('pump.changed.terminalizedExhaustedRolledBack')
                        }
                        planAuthorityState = coordinatorAuthority.current()
                        latestPlanAuthorityState = planAuthorityState
                    }
                }
                continue
            }
            const retryAdvanced = await advanceCoordinatorQueueForStaleRetryAction(retryAction)
            if(!retryAdvanced) continue
            executorAction = retryAction
            planAuthorityState = coordinatorAuthority.current()
            latestPlanAuthorityState = planAuthorityState
            const advancedQueue = planAuthorityState?.queue || {}
            const advancedItem = normalizedHref && advancedQueue[normalizedHref]
                ? advancedQueue[normalizedHref]
                : advancedQueue[coordinatorKey] || advancedQueue[actionSubjectKey] || null
            const liveProfileTabsByHref = await getLiveProfileTabsForPlanning()
            const reclaimTab = getLiveProfileTabForRolledBackQueuedCoordinatorReclaim(
                item,
                null,
                normalizedHref || coordinatorKey,
                liveProfileTabsByHref
            )
            if(reclaimTab &&
                await adoptLiveCoordinatorQueuedTab(advancedItem || item, normalizedHref || coordinatorKey, reclaimTab, ownerTabId, {
                    currentAuthorityState: planAuthorityState
                })) {
                latestPlanAuthorityState = coordinatorAuthority.current()
                if(actionKey) queuedActionKeys.add(actionKey)
                queued += 1
                queuedKeys.push(actionSubjectKey)
                continue
            }
        }
        const plannedAction = await planQueuedTabExecutorAction(executorAction, {
            currentAuthorityState: planAuthorityState
        })
        if(!plannedAction) continue
        if(options.awaitFill === false) {
            plannedAction.planOnlyQueuedAuthority = true
        }
        if(hasQueuedActivationGuard(plannedAction)) {
            incrementQueueWakeupMetric('pump.noop.activationGuardInFlight')
            continue
        }
        // queuedActionKeys was collected before the awaits above. An overlapping plan run (the
        // apply and a scheduled resume can both reach here) may have queued this action since,
        // so re-check the live queue synchronously, right before the enqueue.
        if(actionKey && collectQueuedTabActionKeys(ownerTabId).has(actionKey)) {
            incrementQueueWakeupMetric('pump.noop.planAlreadyQueuedLive')
            continue
        }

        if(superseded()) break
        queueRuntime.enqueueActivationIntent(plannedAction, {
            source: 'machine-intent'
        })
        plannedActions.push(plannedAction)
        if(actionKey) queuedActionKeys.add(actionKey)
        queued += 1
        queuedKeys.push(actionSubjectKey)
    }
    if(batchLimited) {
        incrementQueueWakeupMetric('pump.executorPlanBatchLimited')
        recordQueueWakeupMetricMax('pump.executorPlanBatchLimit', planBatchLimit)
    }

    void sweepOwnedBlockedProfileTabs(ownerTabId)
    const fillOptions = {
        pauseAlreadyChecked: options.pauseAlreadyChecked === true,
        queueOnlyAuthority: options.queueOnlyAuthority === true,
        returnAfterDurableActive: options.returnAfterDurableActive !== false,
        currentAuthorityState: latestPlanAuthorityState || options.currentAuthorityState || null,
        reason: `${options.reason || 'coordinator-executor'}-fill`,
        allowBeforeQuora: options.allowBeforeQuora === true
    }
    let fillResult = null
    let supersededBeforeFill = false
    if(options.awaitFill !== false) {
        // A superseded enqueue leaves its planned actions for the enqueue that replaced it to fill.
        supersededBeforeFill = superseded()
        fillResult = supersededBeforeFill ? null : await fillQueuedTabs(fillOptions)
        if(fillResult?.timedOut === true && plannedActions.length && !queueRuntime.getActivationIntentCount()) {
            const restorableActions = filterRestorableActivationIntents(plannedActions, {
                currentAuthorityState: coordinatorAuthority.current() || latestPlanAuthorityState || null
            })
            if(restorableActions.length) {
                queueRuntime.restoreActivationIntents(restorableActions, {
                    source: 'runtime-effect'
                })
            }
            fillResult = {
                ...fillResult,
                remainingActions: queueRuntime.getActivationIntentCount(),
                restoredActions: restorableActions.length
            }
            incrementQueueWakeupMetric('pump.changed.reprimedFillTimeoutBeforeOpenActions', restorableActions.length)
            scheduleCoordinatorQueueResume(1000, 'queued-tab-fill-timeout-restored-actions', {
                allowBeforeQuora: true
            })
            scheduleQueuedWorkContinuation('queued-tab-fill-timeout-restored-actions')
        }
        else if(fillResult?.reason === 'queued-tab-fill-timeout' &&
            plannedActions.length &&
            !queueRuntime.getActivationIntentCount() &&
            (Number.parseInt(fillResult.openedTabs, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.active, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.schedulerBlockingActive, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.remainingActions, 10) || 0) <= 0) {
            const restorableActions = filterRestorableActivationIntents(plannedActions, {
                currentAuthorityState: coordinatorAuthority.current() || latestPlanAuthorityState || null
            })
            if(restorableActions.length) {
                queueRuntime.restoreActivationIntents(restorableActions, {
                    source: 'runtime-effect'
                })
            }
            fillResult = {
                ...fillResult,
                remainingActions: queueRuntime.getActivationIntentCount(),
                restoredActions: restorableActions.length
            }
            incrementQueueWakeupMetric('pump.changed.reprimedFillTimeoutBeforeOpenActions', restorableActions.length)
            scheduleCoordinatorQueueResume(1000, 'queued-tab-fill-timeout-restored-actions', {
                allowBeforeQuora: true
            })
            scheduleQueuedWorkContinuation('queued-tab-fill-timeout-restored-actions')
        }
        else if(fillResult?.reason === 'no-tab-opened' &&
            plannedActions.length &&
            isQueuedExecutorCapacityConsumed(fillResult)) {
            const restorableActions = filterRestorableActivationIntents(plannedActions, {
                currentAuthorityState: coordinatorAuthority.current() || latestPlanAuthorityState || null
            })
            const restoredCapacityActions = queueRuntime.getActivationIntentCount()
                ? 0
                : restorableActions.length
            if(restoredCapacityActions > 0) {
                queueRuntime.restoreActivationIntents(restorableActions, {
                    source: 'runtime-effect'
                })
                incrementQueueWakeupMetric('pump.changed.restoredCapacityDeferredActions', restoredCapacityActions)
            }
            fillResult = {
                ...fillResult,
                active: Math.max(
                    Number.parseInt(fillResult.active, 10) || 0,
                    queueRuntime.getActiveQueuedTabCount()
                ),
                schedulerBlockingActive: Math.max(
                    Number.parseInt(fillResult.schedulerBlockingActive, 10) || 0,
                    getSchedulerBlockingQueuedExecutorCount()
                ),
                remainingActions: Math.max(
                    Number.parseInt(fillResult.remainingActions, 10) || 0,
                    queueRuntime.getActivationIntentCount()
                ),
                restoredActions: restoredCapacityActions,
                reason: 'queue-capacity-consumed'
            }
            scheduleQueuedWorkContinuation('queue-capacity-consumed')
            scheduleCoordinatorQueueResume(1000, 'queue-capacity-consumed', {
                allowBeforeQuora: true
            })
        }
        else if(fillResult?.reason === 'no-tab-opened' &&
            plannedActions.length &&
            (Number.parseInt(fillResult.remainingActions, 10) || 0) > 0 &&
            (Number.parseInt(fillResult.openedTabs, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.active, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.schedulerBlockingActive, 10) || 0) <= 0) {
            const restorableActions = filterRestorableActivationIntents(plannedActions, {
                currentAuthorityState: coordinatorAuthority.current() || latestPlanAuthorityState || null
            })
            const restoredPendingActions = queueRuntime.getActivationIntentCount()
                ? 0
                : restorableActions.length
            if(restoredPendingActions > 0) {
                queueRuntime.restoreActivationIntents(restorableActions, {
                    source: 'runtime-effect'
                })
                incrementQueueWakeupMetric('pump.changed.restoredNoOpenPendingActions', restoredPendingActions)
            }
            fillResult = {
                ...fillResult,
                remainingActions: Math.max(
                    Number.parseInt(fillResult.remainingActions, 10) || 0,
                    queueRuntime.getActivationIntentCount()
                ),
                restoredPendingActions,
                reason: 'no-tab-opened'
            }
            scheduleCoordinatorQueueResume(1000, 'queued-tab-no-open-attempt-runtime-action-pending', {
                allowBeforeQuora: true
            })
            scheduleQueuedWorkContinuation('queued-tab-no-open-attempt-runtime-action-pending')
        }
        else if(fillResult?.reason === 'no-tab-opened' &&
            plannedActions.length &&
            (Number.parseInt(fillResult.openedTabs, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.active, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.schedulerBlockingActive, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.remainingActions, 10) || 0) <= 0) {
            const reprimeResult = await applyCoordinatorQueueMachineEvent({
                type: 'QUEUED_NO_OPEN_REPRIME',
                plannedActions,
                reason: 'queued-tab-no-open-attempt-reprimed'
            })
            let currentPendingReprimeResult = null
            const noOpenReprimeItems = filterCurrentPendingItemsForPlannedActions(items || [], plannedActions)
            if(!reprimeResult?.reprimed && noOpenReprimeItems.length) {
                currentPendingReprimeResult = await reprimeFreshQueuedTabActionsForCurrentPendingItems(
                    noOpenReprimeItems,
                    ownerTabId,
                    ownerWindowId,
                    {
                        ...options,
                        limit: 1,
                        currentAuthorityState: coordinatorAuthority.current() || latestPlanAuthorityState || null
                    }
                ).catch(error => ({
                    reprimed: 0,
                    keys: [],
                    reason: 'current-pending-no-open-reprime-error',
                    error: error?.message || `${error || ''}`
                }))
                if(currentPendingReprimeResult?.reprimed > 0) {
                    incrementQueueWakeupMetric(
                        'pump.changed.reprimedNoOpenAttemptActions',
                        currentPendingReprimeResult.reprimed
                    )
                    incrementQueueWakeupMetric(
                        'pump.changed.reprimedNoOpenCurrentPendingActions',
                        currentPendingReprimeResult.reprimed
                    )
                }
            }
            fillResult = {
                ...fillResult,
                remainingActions: queueRuntime.getActivationIntentCount(),
                restoredActions: (reprimeResult?.reprimed || 0) +
                    (currentPendingReprimeResult?.reprimed || 0),
                reason: 'no-tab-opened'
            }
            scheduleCoordinatorQueueResume(1000, 'queued-tab-no-open-attempt-reprimed', {
                allowBeforeQuora: true
            })
        }
        else if(fillResult?.reason === 'queued-tab-stale-action-pruned' &&
            plannedActions.length &&
            !queueRuntime.getActivationIntentCount() &&
            (Number.parseInt(fillResult.openedTabs, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.active, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.schedulerBlockingActive, 10) || 0) <= 0 &&
            (Number.parseInt(fillResult.remainingActions, 10) || 0) <= 0) {
            const reprimeResult = await reprimeFreshQueuedTabActionsForPrunedStaleAttempts(
                plannedActions,
                ownerTabId,
                ownerWindowId,
                options
            )
            if(reprimeResult.reprimed > 0) {
                fillResult = {
                    ...fillResult,
                    remainingActions: queueRuntime.getActivationIntentCount(),
                    reprimedActions: reprimeResult.reprimed,
                    reason: 'queued-tab-stale-action-pruned'
                }
                incrementQueueWakeupMetric('pump.changed.reprimedStaleActionPrunedActions', reprimeResult.reprimed)
                scheduleCoordinatorQueueResume(1000, 'queued-tab-stale-action-pruned-reprimed', {
                    allowBeforeQuora: true
                })
                scheduleQueuedWorkContinuation('queued-tab-stale-action-pruned-reprimed')
            }
        }
    }
    else if(plannedActions.length > 0) {
        if(queuedTabFillPromise) {
            const plannedActionsToPreserve = plannedActions.slice()
            queuedTabFillPromise.finally(() => {
                const existingKeys = collectQueuedTabActionKeys(ownerTabId)
                const missingPlannedActions = filterRestorableActivationIntents(plannedActionsToPreserve, {
                    currentAuthorityState: coordinatorAuthority.current() || latestPlanAuthorityState || null
                }).filter(action => {
                    const actionKey = getQueuedTabActionKey(
                        action.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
                        action.profileHref || action.coordinatorKey || action.url || '',
                        action.tabAction || ''
                    )
                    return !actionKey || !existingKeys.has(actionKey)
                })
                if(missingPlannedActions.length) {
                    queueRuntime.restoreActivationIntents(missingPlannedActions, {
                        source: 'runtime-effect'
                    })
                    incrementQueueWakeupMetric('pump.changed.restoredPlanOnlyActionsAfterActiveFill', missingPlannedActions.length)
                }
            }).catch(() => null)
        }
        fillResult = {
            openedTabs: 0,
            active: queueRuntime.getActiveQueuedTabCount(),
            schedulerBlockingActive: getSchedulerBlockingQueuedExecutorCount(),
            remainingActions: queueRuntime.getActivationIntentCount(),
            reason: 'queued-authority-fill-plan-only',
            planOnly: true
        }
    }
    // A superseded enqueue that skipped its fill reports nothing planned. Its planned actions stay as activation intents for the
    // enqueue that replaced it, and the apply pass must not classify them as a failed enqueue (review-2 follow-up).
    if(supersededBeforeFill) {
        recordExecutorStartSupersession(options.cancelToken, 'before-fill')
        return supersededExecutorEnqueueResult()
    }
    // Superseded after the fill decision: the fill ran (or was never awaited), so the result is the real one.
    if(superseded()) recordExecutorStartSupersession(options.cancelToken, options.awaitFill === false ? 'before-fill' : 'after-fill')
    return {
        queued,
        queuedKeys,
        terminalizedExhausted,
        terminalizedExhaustedKeys: [
            ...terminalizedExhaustedKeys,
            ...(preTerminalizedExhausted?.keys || [])
        ],
        fillResult
    }
}

async function shouldOpenQueuedTabAction(action = null, options = {}) {
    const normalizedHref = normalizeQuoraProfileUrl(action?.profileHref || action?.url || '')
    const coordinatorKey = action?.coordinatorKey || (normalizedHref ? normalizedHref : makeProfileResolutionQueueKey(action?.requestedUrl || action?.url || ''))
    if(!normalizedHref && !coordinatorKey) return {open: false, reason: 'invalid-target', decisionBranch: 'invalid-target'}
    if(hasQueuedActivationGuard(action)) {
        return {open: false, reason: 'queued-activation-in-flight', decisionBranch: 'queued-activation-in-flight'}
    }

    let queue = {}
    let progress = {}
    try {
        // This decision only ever looks at this one row (below: `item =
        // queue[normalizedHref] || queue[coordinatorKey]`) -- scoping the
        // progress-shard fetch to it avoids pulling all 32 shards (every
        // profile's progress history) just to check one row's state. The
        // queue/WAL portion of this load is unaffected and already cheap
        // via its own resident-store cache.
        const currentAuthorityState = options.currentAuthorityState || options.authorityState ||
            await verifyCoordinatorAuthorityStateForRowsCheap('shouldOpenQueuedTabAction.fallback', [normalizedHref || coordinatorKey])
        queue = currentAuthorityState.queue
        progress = currentAuthorityState.progress
    }
    catch {
        return {open: false, reason: 'queue-read-failed', authorityUnavailable: true, decisionBranch: 'authority-load-failed'}
    }

    const item = normalizedHref
        ? queue[normalizedHref] || queue[coordinatorKey] || null
        : queue[coordinatorKey] || null
    if(!item) return {open: false, reason: 'missing-coordinator-item', decisionBranch: 'missing-coordinator-item'}

    const actionKind = getCoordinatorActionKindForRequestedAction(action?.actionKind || action?.tabAction || '')
    if(!shouldApplyProgressToCoordinatorItem(item, {actionKind})) {
        return {open: false, reason: 'action-kind-changed', decisionBranch: 'action-kind-changed'}
    }

    if(hasMismatchedCoordinatorAttempt(item, action)) {
        return {open: false, reason: 'stale-attempt', decisionBranch: 'stale-attempt'}
    }

    if(isTerminalCoordinatorStatus(item.status)) {
        if(normalizedHref) {
            await applyCoordinatorQueueMachineEvent({
                type: 'TERMINAL_COORDINATOR_ITEMS_SETTLE',
                options: {profileHrefs: [normalizedHref]}
            })
        }
        return {open: false, reason: 'terminal-coordinator-item', decisionBranch: 'terminal-coordinator-item'}
    }
    if(`${item.status || ''}`.trim() !== 'queued') {
        const progressRecord = normalizedHref ? progress[normalizedHref] || null : null
        if(progressRecord &&
            isSuccessfulProfileNukeRecord(progressRecord) &&
            shouldApplyProgressToCoordinatorItem(item, progressRecord) &&
            !hasMismatchedCoordinatorAttempt(item, progressRecord)) {
            await syncSuccessfulCoordinatorProgress(normalizedHref, progressRecord)
            return {open: false, reason: 'successful-progress-record', decisionBranch: 'successful-progress-record'}
        }
        return {open: false, reason: 'non-queued-coordinator-item', decisionBranch: 'non-queued-coordinator-item'}
    }

    return {open: true, reason: 'queued-coordinator-item', decisionBranch: 'queued-coordinator-item'}
}

async function transitionCoordinatorItemForQueuedTab(action = {}, tab = {}, details = {}) {
    const href = normalizeQuoraProfileUrl(
        action?.profileHref ||
        action?.targetProfileHref ||
        action?.targetUrl ||
        action?.requestedUrl ||
        action?.url ||
        ''
    )
    const coordinatorKey = action?.coordinatorKey || (href ? href : makeProfileResolutionQueueKey(action?.requestedUrl || action?.targetUrl || action?.url || ''))
    if(!href && !coordinatorKey) return false
    const inFlightKey = makeCoordinatorInFlightMutationKey(
        'active-transition',
        coordinatorKey || href,
        details?.attemptId || details?.attemptNumber ? details : action,
        normalizeTabId(tab?.id)
    )
    if(queuedTabActiveTransitionPromises.has(inFlightKey)) {
        incrementQueueWakeupMetric('activeTransition.coalesced')
        return queuedTabActiveTransitionPromises.get(inFlightKey)
    }
    recordFlightRecorderEvent({
        kind: 'active-transition',
        source: 'transitionCoordinatorItemForQueuedTab',
        rowKey: coordinatorKey || href,
        targetUrl: href || action?.requestedUrl || action?.url || '',
        attemptId: getAttemptIdFromValue(details) || getAttemptIdFromValue(action),
        attemptNumber: getAttemptNumberFromValue(details) || getAttemptNumberFromValue(action),
        runId: action?.runId || '',
        tabId: tab?.id || null,
        accepted: true,
        reason: 'attempt'
    })

    const transitionPromise = (getActiveStorageContext()
        ? Promise.resolve().then(() => {
            incrementQueueWakeupMetric('activeTransition.usedCurrentStorageUpdate')
            return applyCoordinatorQueueMachineEvent({
                type: 'TAB_OPENED',
                rowKey: coordinatorKey || href,
                href,
                coordinatorKey,
                action,
                tab,
                details
            }, {
                reason: 'ordinaryMutation'
            })
        })
        : enqueueSpaceFeedStorageUpdate(() => {
            return applyCoordinatorQueueMachineEvent({
                type: 'TAB_OPENED',
                rowKey: coordinatorKey || href,
                href,
                coordinatorKey,
                action,
                tab,
                details
            }, {
                reason: 'ordinaryMutation'
            })
        }, {
            reason: 'active-transition',
            timeoutMs: QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS
        }))
        .finally(() => {
            queuedTabActiveTransitionPromises.delete(inFlightKey)
        })
    queuedTabActiveTransitionPromises.set(inFlightKey, transitionPromise)
    return transitionPromise
}

async function reprimeQueuedTabActionsForNoOpenEvent(event = {}) {
    const plannedActions = Array.isArray(event.plannedActions)
        ? event.plannedActions.filter(Boolean)
        : []
    if(!plannedActions.length) {
        return {
            changed: false,
            reprimed: 0,
            remainingActions: queueRuntime.getActivationIntentCount(),
            reason: 'no-planned-actions'
        }
    }
    // 2026-10-03: scoped to plannedActions' own hrefs -- this function's
    // progress usage downstream is nonexistent (same as the other reprime*
    // functions above), so the full 32-shard fetch was pure waste.
    const knownHrefs = getNormalizedProfileHrefList(
        plannedActions.map(action => action?.profileHref || action?.url || '')
    )
    const currentAuthorityState = event.currentAuthorityState?.queue
        ? event.currentAuthorityState
        : await coordinatorQueueReader.currentAuthority({}, {profileHrefs: knownHrefs})
    const queue = currentAuthorityState?.queue || null
    const ownerTabId = event.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID
    const ownerWindowId = event.ownerWindowId || null
    const queuedActionKeys = new Set(queueRuntime.mapActivationIntents(action =>
        getQueuedTabActionKey(
            action.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
            action.profileHref || action.coordinatorKey || action.url || '',
            action.tabAction || ''
        )
    ))
    const missingPlannedActions = []
    for(const action of plannedActions) {
        const actionKey = getQueuedTabActionKey(
            action.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
            action.profileHref || action.coordinatorKey || action.url || '',
            action.tabAction || ''
        )
        if(actionKey && queuedActionKeys.has(actionKey)) continue

        let plannedAction = null
        if(queue) {
            const normalizedHref = normalizeQuoraProfileUrl(action.profileHref || action.url || '')
            const coordinatorKey = action.coordinatorKey || (normalizedHref
                ? normalizedHref
                : makeProfileResolutionQueueKey(action.requestedUrl || action.url || ''))
            const entry = coordinatorKey && queue[coordinatorKey]
                ? {key: coordinatorKey, item: queue[coordinatorKey]}
                : findCoordinatorQueueEntryForHref(queue, normalizedHref)
            const item = entry?.item || null
            if(item && `${item.status || ''}`.trim() === 'queued') {
                const tabAction = getCoordinatorItemExecutorTabAction(item, action.tabAction || event.tabAction)
                const actionSubjectKey = getCoordinatorItemHref(item) ||
                    getCoordinatorItemQueueKey(item, entry?.key || coordinatorKey) ||
                    normalizedHref ||
                    coordinatorKey
                const executorAction = buildCoordinatorExecutorActionForQueuedItem(
                    item,
                    ownerTabId,
                    ownerWindowId,
                    {
                        fallbackKey: actionSubjectKey,
                        tabAction
                    }
                )
                plannedAction = executorAction
                    ? await planQueuedTabExecutorAction(executorAction, {currentAuthorityState})
                    : null
            }
        }
        if(!plannedAction && !queue) {
            plannedAction = action
        }
        if(!plannedAction) continue
        if(hasQueuedActivationGuard(plannedAction)) continue

        const plannedKey = getQueuedTabActionKey(
            plannedAction.ownerTabId || SERVICE_WORKER_QUEUE_OWNER_ID,
            plannedAction.profileHref || plannedAction.coordinatorKey || plannedAction.url || '',
            plannedAction.tabAction || ''
        )
        if(plannedKey && queuedActionKeys.has(plannedKey)) continue
        missingPlannedActions.push(plannedAction)
        if(plannedKey) queuedActionKeys.add(plannedKey)
    }
    if(missingPlannedActions.length) {
        queueRuntime.restoreActivationIntents(missingPlannedActions, {
            source: 'runtime-effect'
        })
        incrementQueueWakeupMetric(
            event.metricName || 'pump.changed.reprimedNoOpenAttemptActions',
            event.metricCount || plannedActions.length
        )
    }
    return {
        changed: missingPlannedActions.length > 0,
        reprimed: missingPlannedActions.length,
        remainingActions: queueRuntime.getActivationIntentCount(),
        reason: event.reason || 'queued-tab-no-open-attempt-reprimed'
    }
}

async function planQueuedActivationIntentForSlotEvent(event = {}) {
    const next = queueRuntime.consumeActivationIntent()
    if(!next) {
        return {
            accepted: false,
            changed: false,
            reason: 'no-activation-intent',
            remainingActions: queueRuntime.getActivationIntentCount()
        }
    }

    if(isCoordinatorPauseRequestedLocally()) {
        queueRuntime.requeueActivationIntent(next, {
            source: 'runtime-effect'
        })
        return {
            accepted: false,
            changed: false,
            action: next,
            requeued: true,
            paused: true,
            reason: 'coordinator-paused',
            remainingActions: queueRuntime.getActivationIntentCount()
        }
    }

    if(next?.planOnlyQueuedAuthority === true && event.executePlanOnlyQueuedAuthority !== true) {
        queueRuntime.requeueActivationIntent(next, {
            source: 'runtime-effect'
        })
        return {
            accepted: false,
            changed: false,
            action: next,
            requeued: true,
            planOnlyQueuedAuthorityPreserved: true,
            reason: 'plan-only-queued-authority-preserved',
            remainingActions: queueRuntime.getActivationIntentCount()
        }
    }

    if(queueRuntime.hasPausedQueuedOwner(next.ownerTabId)) {
        if(next.ownerTabId === SERVICE_WORKER_QUEUE_OWNER_ID) {
            queueRuntime.resumeQueuedOwner(SERVICE_WORKER_QUEUE_OWNER_ID)
            return {
                accepted: true,
                changed: true,
                action: next,
                clearedStaleServiceWorkerOwnerPause: true,
                reason: 'cleared-stale-service-worker-owner-pause',
                remainingActions: queueRuntime.getActivationIntentCount()
            }
        }

        rememberCanceledOwnerUrls(next.ownerTabId, next.url ? [next.url] : [])
        return {
            accepted: false,
            changed: true,
            action: next,
            canceledPausedOwner: true,
            reason: 'paused-queued-owner-canceled',
            remainingActions: queueRuntime.getActivationIntentCount()
        }
    }

    if(hasQueuedActivationGuard(next)) {
        return {
            accepted: false,
            changed: false,
            action: next,
            activationGuardInFlight: true,
            reason: 'queued-activation-in-flight',
            remainingActions: queueRuntime.getActivationIntentCount()
        }
    }

    return {
        accepted: true,
        changed: true,
        action: next,
        reason: 'activation-intent-selected',
        remainingActions: queueRuntime.getActivationIntentCount()
    }
}

